/* 2ᵉ Bac : exercices supplémentaires (séries de 7 exercices). Outils : js/exos-plus.js, js/exos-tc2.js, js/exos-1bac2.js. */
'use strict';
const WAVE = (pts, extra) => SVG(460, 140, `<line x1="20" y1="70" x2="440" y2="70" stroke="#9aa6bf"/><polyline points="${pts}" fill="none" stroke="#1f6fe0" stroke-width="3"/>` + (extra || ''));
const sinPts = (x0, x1, amp, lam, y0) => Array.from({ length: Math.round((x1 - x0) / 2) + 1 }, (_, i) => { const x = x0 + i * 2; return x + ',' + ((y0 || 70) - amp * Math.sin(2 * Math.PI * (x - x0) / lam)).toFixed(1); }).join(' ');
const dampPts = (n, T, tau, amp) => Array.from({ length: n }, (_, i) => i);

/* ===== Ondes ===== */
addExos('2b-ondes', [
  { d: 1, t: 'Propagation d’une perturbation', fig: SVG(460, 160, `<line x1="20" y1="60" x2="440" y2="60" stroke="#9aa6bf"/><path d="M20 60 L60 60 Q 80 20 100 60 L440 60" fill="none" stroke="#9aa6bf" stroke-width="2" stroke-dasharray="5 4"/><path d="M20 60 L180 60 Q 200 20 220 60 L440 60" fill="none" stroke="#1f6fe0" stroke-width="3"/><text x="60" y="90" font-size="11">t₁ = 0</text><text x="180" y="90" font-size="11">t₂ = 0,20 s</text><line x1="80" y1="110" x2="200" y2="110" stroke="#d93a4a" stroke-width="2"/><text x="120" y="128" fill="#d93a4a" font-size="11">60 cm</text><circle cx="400" cy="60" r="4" fill="#12946a"/><text x="394" y="50" font-size="11">M</text><text x="300" y="140" font-size="11">SM = 1,5 m</text>`),
    q: TX`On a représenté une corde à deux instants : la perturbation a avancé de 60 cm en 0,20 s.<br>1) Calculer la célérité de l’onde.<br>2) La perturbation est partie de S à \(t = 0\). À quelle date atteint-elle M (SM = 1,5 m) ?<br>3) L’onde est-elle transversale ou longitudinale ?`,
    s: TX`1) \(v = \dfrac{0{,}60}{0{,}20} = 3{,}0\ \text{m/s}\).<br>2) \(\tau = \dfrac{1{,}5}{3{,}0} = 0{,}50\ \text{s}\).<br>3) Transversale : les points de la corde se déplacent perpendiculairement à la direction de propagation.` },
  { d: 2, t: 'Élongations de S et de M', fig: cfig({ w: 440, h: 200, x1: 1.2, xs: 0.2, y0: -1, y1: 2, ys: 1, xl: 't (s)', yl: 'y (cm)', f: t => t < 0.2 ? 1.5 * Math.sin(Math.PI * t / 0.2) : 0, fmtx: x => String(x).replace('.', ','), ext: (X, Y) => `<polyline points="${Array.from({ length: 41 }, (_, i) => { const t = 0.6 + i * 0.005; return X(t).toFixed(1) + ',' + Y(1.5 * Math.sin(Math.PI * (t - 0.6) / 0.2)).toFixed(1); }).join(' ')}" fill="none" stroke="#d93a4a" stroke-width="2.6"/><text x="${X(0.05)}" y="${Y(1.8)}" fill="#1f6fe0">S</text><text x="${X(0.65)}" y="${Y(1.8)}" fill="#d93a4a">M</text>` }),
    q: TX`Le graphe donne l’élongation de la source S et celle d’un point M d’une corde, situé à 1,2 m de S.<br>1) Déterminer le retard de M par rapport à S.<br>2) En déduire la célérité.<br>3) Quelle est la durée de la perturbation ? Quelle longueur de corde occupe-t-elle ?`,
    s: TX`1) \(\tau = 0{,}60\ \text{s}\) (même forme décalée).<br>2) \(v = \dfrac{1{,}2}{0{,}60} = 2{,}0\ \text{m/s}\).<br>3) \(\Delta t = 0{,}20\ \text{s}\) ; longueur \(v\,\Delta t = 0{,}40\ \text{m}\).` },
  { d: 3, t: 'Localiser un séisme', fig: SVG(460, 140, `<line x1="20" y1="70" x2="440" y2="70" stroke="#9aa6bf"/><polyline points="${Array.from({ length: 211 }, (_, i) => { const x = 20 + i * 2; const a = x > 100 && x < 220 ? 12 * Math.sin(x) : x > 280 ? 30 * Math.sin(x * 0.7) * Math.exp(-(x - 280) / 120) : 1; return x + ',' + (70 - a).toFixed(1); }).join(' ')}" fill="none" stroke="#1f6fe0" stroke-width="1.5"/><text x="96" y="20" font-size="11">arrivée des ondes P</text><text x="272" y="20" font-size="11">arrivée des ondes S</text><line x1="100" y1="110" x2="280" y2="110" stroke="#d93a4a" stroke-width="2"/><text x="170" y="128" fill="#d93a4a" font-size="11">Δt = 30 s</text>`),
    q: TX`Un séisme émet des ondes P (\(v_P = 6{,}0\ \text{km/s}\)) et des ondes S (\(v_S = 3{,}5\ \text{km/s}\)) au même instant. Une station enregistre les ondes S 30 s après les ondes P.<br>1) Quelles ondes arrivent les premières ? Pourquoi ?<br>2) Exprimer \(\Delta t\) en fonction de la distance d et des célérités.<br>3) Calculer la distance d entre la station et le foyer.`,
    s: TX`1) Les ondes P, plus rapides.<br>2) \(\Delta t = \dfrac{d}{v_S} - \dfrac{d}{v_P}\).<br>3) \(d = \dfrac{\Delta t}{1/v_S - 1/v_P} = \dfrac{30}{0{,}2857 - 0{,}1667} \approx 2{,}5\times10^{2}\ \text{km}\).` },
]);

addExos('2b-ondes-per', [
  { d: 1, t: 'Lire une longueur d’onde', fig: WAVE(sinPts(20, 440, 40, 140), `<line x1="20" y1="125" x2="440" y2="125" stroke="#d93a4a" stroke-width="2"/><text x="200" y="138" fill="#d93a4a" font-size="11">30 cm (3 longueurs d’onde)</text>`),
    q: TX`L’aspect d’une corde parcourue par une onde sinusoïdale de fréquence 50 Hz est représenté ; trois longueurs d’onde occupent 30 cm.<br>1) Déterminer λ.<br>2) Calculer la célérité et la période.<br>3) Deux points distants de 15 cm vibrent-ils en phase ?`,
    s: TX`1) \(\lambda = 10\ \text{cm}\).<br>2) \(v = \lambda f = 0{,}10\times50 = 5{,}0\ \text{m/s}\) ; \(T = 20\ \text{ms}\).<br>3) \(15 = 1{,}5\lambda = 3\times\dfrac{\lambda}{2}\) : opposition de phase.` },
  { d: 2, t: 'Ultrasons et récepteurs', fig: SVG(460, 140, `<rect x="20" y="50" width="40" height="40" fill="#5b6577"/><text x="16" y="110" font-size="11">émetteur 40 kHz</text><rect x="200" y="55" width="20" height="30" fill="#1f6fe0"/><text x="190" y="110" font-size="11">R₁</text><rect x="300" y="55" width="20" height="30" fill="#d93a4a"/><text x="292" y="110" font-size="11">R₂ (mobile)</text>`),
    q: TX`Un émetteur d’ultrasons de fréquence 40 kHz est suivi de deux récepteurs. On éloigne \(R_2\) de \(R_1\) : les signaux sont en phase pour la 10ᵉ fois après un déplacement de 8,5 cm.<br>1) Que vaut la distance entre deux positions successives où les signaux sont en phase ?<br>2) En déduire λ et la célérité des ultrasons.<br>3) Les ultrasons sont-ils audibles ?`,
    s: TX`1) Une longueur d’onde.<br>2) \(10\lambda = 8{,}5\ \text{cm}\) : \(\lambda = 8{,}5\ \text{mm}\) ; \(v = \lambda f = 8{,}5\times10^{-3}\times4\times10^{4} = 340\ \text{m/s}\).<br>3) Non : \(f > 20\ \text{kHz}\).` },
  { d: 3, t: 'Un milieu dispersif ?', fig: TBL(['f (Hz)', '10', '15', '20'], [['λ (cm)', '2,4', '1,5', '1,1']], 380),
    q: TX`On mesure la longueur d’onde des ondes à la surface de l’eau d’une cuve pour plusieurs fréquences.<br>1) Calculer la célérité pour chaque fréquence.<br>2) Le milieu est-il dispersif ? Justifier.<br>3) On place dans la cuve une fente de largeur 1 cm : pour quelle fréquence la diffraction est-elle la plus marquée ?`,
    s: TX`1) 0,24 m/s ; 0,225 m/s ; 0,22 m/s.<br>2) Oui : la célérité dépend de la fréquence.<br>3) Pour 10 Hz : λ = 2,4 cm est la plus grande devant la largeur de la fente.` },
]);

addExos('2b-lumiere', [
  { d: 1, t: 'Largeur de la tache centrale', fig: SVG(460, 120, `<rect x="20" y="50" width="40" height="20" fill="#d93a4a"/><line x1="60" y1="60" x2="150" y2="60" stroke="#d93a4a" stroke-width="3"/><rect x="150" y="10" width="6" height="46" fill="#14213d"/><rect x="150" y="64" width="6" height="46" fill="#14213d"/><line x1="156" y1="60" x2="420" y2="30" stroke="#d93a4a" stroke-dasharray="4 3"/><line x1="156" y1="60" x2="420" y2="90" stroke="#d93a4a" stroke-dasharray="4 3"/><rect x="420" y="10" width="8" height="100" fill="#9aa6bf"/><text x="280" y="114" font-size="11">D = 2,0 m</text>`),
    q: TX`Un laser (\(\lambda = 633\ \text{nm}\)) éclaire une fente de largeur \(a = 0{,}10\ \text{mm}\) ; l’écran est à \(D = 2{,}0\ \text{m}\).<br>1) Calculer l’écart angulaire θ.<br>2) Calculer la largeur L de la tache centrale.<br>3) Que devient L si on remplace le laser par un laser vert (532 nm) ?`,
    s: TX`1) \(\theta = \dfrac{6{,}33\times10^{-7}}{1{,}0\times10^{-4}} \approx 6{,}3\times10^{-3}\ \text{rad}\).<br>2) \(L = 2D\theta \approx 2{,}5\ \text{cm}\).<br>3) L diminue (proportionnelle à λ) : environ 2,1 cm.` },
  { d: 2, t: 'Mesurer λ avec un graphe', fig: cfig({ w: 420, h: 230, x1: 20, xs: 5, y1: 14, ys: 2, xl: '1/a (mm⁻¹)', yl: 'θ (mrad)', f: x => 0.65 * x, ext: (X, Y) => [5, 10, 15, 20].map(x => `<circle cx="${X(x)}" cy="${Y(0.65 * x)}" r="4" fill="#d93a4a"/>`).join('') }),
    q: TX`On mesure l’écart angulaire θ pour plusieurs fentes et on trace \(\theta = f(1/a)\).<br>1) La courbe est-elle en accord avec \(\theta = \lambda/a\) ?<br>2) Déterminer la pente et en déduire λ.<br>3) De quelle couleur est la lumière ?`,
    s: TX`1) Oui : droite passant par l’origine.<br>2) Pente \(= 0{,}65\ \text{mrad·mm} = 6{,}5\times10^{-7}\ \text{m}\) : \(\lambda = 650\ \text{nm}\).<br>3) Rouge.` },
  { d: 3, t: 'Déviation par un prisme', fig: SVG(380, 200, `<polygon points="190,20 80,180 300,180" fill="#eaf1fd" stroke="#14213d" stroke-width="2"/><line x1="10" y1="80" x2="135" y2="100" stroke="#d93a4a" stroke-width="2.5"/><line x1="135" y1="100" x2="245" y2="100" stroke="#d93a4a" stroke-width="2.5"/><line x1="245" y1="100" x2="370" y2="140" stroke="#d93a4a" stroke-width="2.5"/><text x="180" y="60" font-size="11">A = 60°</text>`),
    q: TX`Un prisme d’angle \(A = 60°\) et d’indice \(n = 1{,}50\) reçoit un rayon sous l’incidence \(i = 45°\).<br>1) Calculer l’angle de réfraction r sur la première face.<br>2) En déduire r′ puis l’angle d’émergence i′.<br>3) Calculer la déviation D.`,
    s: TX`1) \(\sin r = \dfrac{\sin45°}{1{,}5} \approx 0{,}471\) : \(r \approx 28{,}1°\).<br>2) \(r' = A - r \approx 31{,}9°\) ; \(\sin i' = 1{,}5\sin31{,}9° \approx 0{,}792\) : \(i' \approx 52{,}4°\).<br>3) \(D = i + i' - A \approx 37{,}4°\).` },
]);

addExos('2b-noyaux', [
  { d: 1, t: 'Masse et énergie', fig: SVG(260, 160, ball(130, 80, 60, '#ffb23e', '') + `<text x="130" y="86" text-anchor="middle" font-weight="bold">Soleil</text>`),
    q: TX`\(c = 3{,}0\times10^{8}\ \text{m/s}\).<br>1) Quelle énergie correspond à une masse de 1,0 g ?<br>2) Le Soleil perd chaque seconde \(4{,}3\times10^{9}\ \text{kg}\). Calculer la puissance qu’il rayonne.`,
    s: TX`1) \(E = mc^2 = 10^{-3}\times9\times10^{16} = 9{,}0\times10^{13}\ \text{J}\).<br>2) \(P = \dfrac{\Delta m\,c^2}{\Delta t} \approx 3{,}9\times10^{26}\ \text{W}\).` },
  { d: 2, t: 'Énergie de liaison du lithium 7', fig: SVG(260, 140, `${Array.from({ length: 7 }, (_, i) => { const a = i * 2.4, r = 9 * Math.sqrt(i + 0.5); return `<circle cx="${(80 + r * Math.cos(a)).toFixed(1)}" cy="${(70 + r * Math.sin(a)).toFixed(1)}" r="9" fill="${i % 2 ? '#d93a4a' : '#9aa6bf'}" stroke="#14213d"/>`; }).join('')}<text x="140" y="74" font-size="13">⁷₃Li</text>`),
    q: TX`Données : \(m_p = 1{,}00728\ \text{u}\), \(m_n = 1{,}00866\ \text{u}\), \(m({}^{7}_{3}\text{Li}) = 7{,}01436\ \text{u}\), \(1\ \text{u} = 931{,}5\ \text{MeV}/c^2\).<br>1) Calculer le défaut de masse.<br>2) Calculer l’énergie de liaison et l’énergie de liaison par nucléon.<br>3) Comparer à l’hélium 4 (7,07 MeV/nucléon).`,
    s: TX`1) \(\Delta m = 3\times1{,}00728 + 4\times1{,}00866 - 7{,}01436 = 0{,}04212\ \text{u}\).<br>2) \(E_\ell \approx 39{,}2\ \text{MeV}\) ; \(\mathcal E \approx 5{,}6\ \text{MeV/nucléon}\).<br>3) Le lithium 7 est moins stable que l’hélium 4.` },
  { d: 3, t: 'Diagramme énergétique d’une fusion', fig: SVG(380, 220, `<line x1="60" y1="40" x2="180" y2="40" stroke="#14213d" stroke-width="2"/><text x="190" y="44" font-size="11">nucléons séparés</text><line x1="60" y1="120" x2="180" y2="120" stroke="#14213d" stroke-width="2"/><text x="190" y="124" font-size="11">²H + ²H</text><line x1="60" y1="190" x2="180" y2="190" stroke="#14213d" stroke-width="2"/><text x="190" y="194" font-size="11">³He + n</text><line x1="120" y1="120" x2="120" y2="186" stroke="#d93a4a" stroke-width="2.5"/><text x="128" y="160" fill="#d93a4a" font-size="11">E_lib</text>`),
    q: TX`On étudie \({}^{2}_{1}\text{H} + {}^{2}_{1}\text{H} \to {}^{3}_{2}\text{He} + {}^{1}_{0}\text{n}\). Masses : \({}^{2}\text{H}\) : 2,01355 u ; \({}^{3}\text{He}\) : 3,01493 u ; n : 1,00866 u.<br>1) Vérifier les lois de conservation.<br>2) Calculer l’énergie libérée en MeV.<br>3) Calculer l’énergie libérée par la fusion de 1,0 g de deutérium (\(M = 2{,}0\ \text{g/mol}\)).`,
    s: TX`1) \(2 + 2 = 3 + 1\) ; \(1 + 1 = 2 + 0\).<br>2) \(\Delta m = 2\times2{,}01355 - (3{,}01493 + 1{,}00866) = 3{,}51\times10^{-3}\ \text{u}\) ; \(E_{lib} \approx 3{,}27\ \text{MeV}\).<br>3) \(N = \dfrac{1}{2}\times6{,}02\times10^{23}\) noyaux, soit \(1{,}5\times10^{23}\) réactions : \(E \approx 4{,}9\times10^{23}\ \text{MeV} \approx 7{,}9\times10^{10}\ \text{J}\).` },
]);

/* ===== Électricité ===== */
const ord1 = (x1, ym, tau, rising) => t => rising ? ym * (1 - Math.exp(-t / tau)) : ym * Math.exp(-t / tau);
addExos('2b-rc', [
  { d: 1, t: 'Lire la constante de temps', fig: cfig({ w: 420, h: 220, x1: 10, xs: 2, y1: 7, ys: 1, xl: 't (ms)', yl: 'u_C (V)', f: ord1(10, 6, 2, true), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(2)}" y2="${Y(6)}" stroke="#d93a4a" stroke-dasharray="5 3"/><line x1="${X(0)}" y1="${Y(6)}" x2="${X(10)}" y2="${Y(6)}" stroke="#9aa6bf" stroke-dasharray="4 3"/>` }),
    q: TX`La courbe représente la charge d’un condensateur à travers une résistance \(R = 1{,}0\ \text{k}\Omega\).<br>1) Déterminer E et τ (tangente à l’origine).<br>2) En déduire C.<br>3) Vérifier la valeur de \(u_C\) à \(t = \tau\).`,
    s: TX`1) \(E = 6{,}0\ \text{V}\) ; \(\tau = 2{,}0\ \text{ms}\).<br>2) \(C = \dfrac{\tau}{R} = 2{,}0\ \mu\text{F}\).<br>3) \(u_C(\tau) = 0{,}63\times6 \approx 3{,}8\ \text{V}\), conforme à la courbe.` },
  { d: 2, t: 'Décharge et énergie restante', fig: cfig({ w: 420, h: 220, x1: 2.5, xs: 0.5, y1: 13, ys: 2, xl: 't (s)', yl: 'u_C (V)', f: ord1(2.5, 12, 0.47, false), fmtx: x => String(x).replace('.', ',') }),
    q: TX`Un condensateur \(C = 470\ \mu\text{F}\), chargé sous 12 V, se décharge dans \(R = 1{,}0\ \text{k}\Omega\).<br>1) Calculer τ et l’énergie initiale.<br>2) À quelle date \(u_C = 6{,}0\ \text{V}\) ?<br>3) Quelle fraction de l’énergie reste-t-il à cette date ?`,
    s: TX`1) \(\tau = 0{,}47\ \text{s}\) ; \(E_0 = \tfrac12\times470\times10^{-6}\times144 \approx 3{,}4\times10^{-2}\ \text{J}\).<br>2) \(e^{-t/\tau} = \tfrac12\) : \(t = \tau\ln2 \approx 0{,}33\ \text{s}\).<br>3) \(E \propto u_C^2\) : un quart de l’énergie.` },
  { d: 3, t: 'Le flash d’un appareil photo', fig: SVG(300, 140, `<rect x="40" y="40" width="160" height="70" rx="10" fill="#5b6577"/><circle cx="160" cy="75" r="22" fill="#14213d"/><rect x="60" y="30" width="50" height="16" fill="#ffd27a"/><text x="220" y="80" font-size="11">C = 100 µF</text>`),
    q: TX`Le condensateur d’un flash (\(C = 100\ \mu\text{F}\)) est chargé sous 300 V, puis se décharge dans la lampe en 1,0 ms environ.<br>1) Calculer la charge et l’énergie stockées.<br>2) Calculer la puissance moyenne lors de l’éclair.<br>3) Pour la charge, on utilise une résistance de 10 kΩ. Durée de charge pratiquement complète ?`,
    s: TX`1) \(q = CU = 3{,}0\times10^{-2}\ \text{C}\) ; \(E = \tfrac12 CU^2 = 4{,}5\ \text{J}\).<br>2) \(P \approx \dfrac{4{,}5}{10^{-3}} = 4{,}5\ \text{kW}\).<br>3) \(5\tau = 5RC = 5\ \text{s}\).` },
]);

addExos('2b-rl', [
  { d: 1, t: 'Exploiter i(t)', fig: cfig({ w: 420, h: 220, x1: 25, xs: 5, y1: 0.12, ys: 0.02, xl: 't (ms)', yl: 'i (A)', f: ord1(25, 0.1, 5, true), fmty: y => String(+y.toFixed(2)).replace('.', ','), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(5)}" y2="${Y(0.1)}" stroke="#d93a4a" stroke-dasharray="5 3"/>` }),
    q: TX`La courbe montre l’établissement du courant dans un circuit RL alimenté sous \(E = 6{,}0\ \text{V}\).<br>1) Déterminer \(I_0\) et τ.<br>2) En déduire la résistance totale \(R_T\) puis l’inductance L.`,
    s: TX`1) \(I_0 = 0{,}10\ \text{A}\) ; \(\tau = 5{,}0\ \text{ms}\).<br>2) \(R_T = \dfrac{E}{I_0} = 60\ \Omega\) ; \(L = \tau R_T = 0{,}30\ \text{H}\).` },
  { d: 2, t: 'Tension aux bornes de la bobine', fig: SVG(420, 160, W_('60,30 360,30 360,130 60,130 60,30') + GEN(60, 80, 'E', 1) + RES(180, 30, 'R') + `<rect x="300" y="18" width="50" height="24" fill="#d98200" opacity=".7"/><text x="306" y="12" font-size="11">bobine (L, r)</text>`),
    q: TX`Un circuit comporte \(E = 12\ \text{V}\), \(R = 40\ \Omega\) et une bobine (\(L = 0{,}50\ \text{H}\), \(r = 10\ \Omega\)).<br>1) Que vaut \(u_L\) juste après la fermeture ? Justifier.<br>2) Calculer \(I_0\) et \(u_L\) en régime permanent.<br>3) Calculer τ et l’énergie stockée en régime permanent.`,
    s: TX`1) \(i(0) = 0\) donc \(u_R = 0\) et \(u_L = E = 12\ \text{V}\).<br>2) \(I_0 = \dfrac{12}{50} = 0{,}24\ \text{A}\) ; \(u_L = rI_0 = 2{,}4\ \text{V}\).<br>3) \(\tau = \dfrac{0{,}5}{50} = 10\ \text{ms}\) ; \(E_m = \tfrac12\times0{,}5\times0{,}24^2 \approx 1{,}4\times10^{-2}\ \text{J}\).` },
  { d: 3, t: 'Vérifier une solution', fig: SVG(300, 100, `<text x="150" y="56" text-anchor="middle" font-size="18">i(t) = A·(1 − e^(−t/τ))</text>`),
    q: TX`On établit le courant dans un dipôle RL (\(R_T\), L) sous la tension E.<br>1) Établir l’équation différentielle vérifiée par i.<br>2) Montrer que \(i = A(1 - e^{-t/\tau})\) est solution et exprimer A et τ.<br>3) Calculer le pourcentage de \(I_0\) atteint à \(t = \tau\) et à \(t = 5\tau\).`,
    s: TX`1) \(E = R_Ti + L\dfrac{di}{dt}\).<br>2) \(\dfrac{di}{dt} = \dfrac{A}{\tau}e^{-t/\tau}\) ; en remplaçant : \(R_TA + Ae^{-t/\tau}\Big(\dfrac{L}{\tau} - R_T\Big) = E\) pour tout t, d’où \(A = \dfrac{E}{R_T}\) et \(\tau = \dfrac{L}{R_T}\).<br>3) 63 % puis 99 %.` },
]);

addExos('2b-rlc', [
  { d: 1, t: 'Lire la pseudo-période', fig: cfig({ w: 420, h: 220, x1: 16, xs: 2, y0: -6, y1: 6, ys: 2, xl: 't (ms)', yl: 'u_C (V)', f: t => 6 * Math.exp(-t / 14) * Math.cos(2 * Math.PI * t / 4) }),
    q: TX`Un condensateur de capacité \(C = 1{,}0\ \mu\text{F}\) se décharge dans une bobine.<br>1) Nommer le régime observé.<br>2) Déterminer la pseudo-période T.<br>3) En prenant \(T \approx T_0\), calculer l’inductance L.`,
    s: TX`1) Pseudo-périodique (amplitude décroissante).<br>2) \(T = 4{,}0\ \text{ms}\).<br>3) \(L = \dfrac{T^2}{4\pi^2C} = \dfrac{(4\times10^{-3})^2}{4\pi^2\times10^{-6}} \approx 0{,}41\ \text{H}\).` },
  { d: 2, t: 'Énergie perdue en une période', fig: cfig({ w: 420, h: 220, x1: 8, xs: 1, y0: -6, y1: 6, ys: 2, xl: 't (ms)', yl: 'u_C (V)', f: t => 6 * Math.pow(2 / 3, t / 4) * Math.cos(2 * Math.PI * t / 4) }),
    q: TX`Dans un circuit RLC (\(C = 1{,}0\ \mu\text{F}\)), \(u_C\) vaut 6,0 V à \(t = 0\) (i = 0) et 4,0 V une pseudo-période plus tard (i = 0).<br>1) Calculer l’énergie totale à ces deux instants.<br>2) Calculer l’énergie dissipée pendant une pseudo-période. Sous quelle forme ?`,
    s: TX`1) \(\mathcal E_0 = \tfrac12\times10^{-6}\times36 = 18\ \mu\text{J}\) ; \(\mathcal E_1 = 8{,}0\ \mu\text{J}\).<br>2) \(10\ \mu\text{J}\) dissipés par effet Joule dans les résistances.` },
  { d: 3, t: 'Circuit LC idéal', fig: SVG(300, 140, W_('60,30 240,30 240,110 60,110 60,30') + `<line x1="50" y1="64" x2="70" y2="64" stroke="#14213d" stroke-width="3"/><line x1="50" y1="76" x2="70" y2="76" stroke="#14213d" stroke-width="3"/><text x="30" y="74">C</text><path d="M240 40 q14 8 0 16 q14 8 0 16 q14 8 0 16 q14 8 0 16" fill="none" stroke="#d98200" stroke-width="3"/><text x="258" y="74">L</text>`),
    q: TX`Un condensateur (\(C = 2{,}0\ \mu\text{F}\)) chargé sous 10 V est relié à une bobine idéale (\(L = 0{,}20\ \text{H}\), r = 0).<br>1) Établir l’équation différentielle vérifiée par q.<br>2) Vérifier que \(q = Q_m\cos(2\pi t/T_0)\) est solution et calculer \(T_0\).<br>3) Calculer \(Q_m\), puis l’intensité maximale.`,
    s: TX`1) \(u_L + u_C = 0\) : \(L\ddot q + \dfrac{q}{C} = 0\).<br>2) \(\ddot q = -\dfrac{4\pi^2}{T_0^2}q\) donc \(T_0 = 2\pi\sqrt{LC} = 2\pi\sqrt{4\times10^{-7}} \approx 4{,}0\ \text{ms}\).<br>3) \(Q_m = CU = 2{,}0\times10^{-5}\ \text{C}\) ; \(I_m = \dfrac{2\pi}{T_0}Q_m \approx 3{,}2\times10^{-2}\ \text{A}\).` },
]);

addExos('2b-rlc-force', [
  { d: 1, t: 'Fréquence de résonance', fig: SVG(420, 120, W_('60,30 360,30 360,100 60,100 60,30') + `<circle cx="60" cy="65" r="14" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="60" y="70" text-anchor="middle">~</text>` + RES(140, 30, 'R') + `<text x="220" y="22">L = 50 mH</text><text x="300" y="22">C = 2 µF</text>`),
    q: TX`Un circuit RLC série (\(L = 50\ \text{mH}\), \(C = 2{,}0\ \mu\text{F}\)) est alimenté par un GBF.<br>1) Calculer la fréquence de résonance.<br>2) Que valent Z et φ à cette fréquence ?`,
    s: TX`1) \(N_0 = \dfrac{1}{2\pi\sqrt{5\times10^{-2}\times2\times10^{-6}}} \approx 503\ \text{Hz}\).<br>2) \(Z = R\) ; \(\varphi = 0\).` },
  { d: 2, t: 'Mesures à la résonance', fig: SVG(300, 100, `<text x="150" y="40" text-anchor="middle" font-size="14">U = 6,0 V ; I₀ = 60 mA</text><text x="150" y="70" text-anchor="middle" font-size="14">L = 50 mH ; N₀ = 503 Hz</text>`),
    q: TX`À la résonance, on mesure \(U = 6{,}0\ \text{V}\) et \(I_0 = 60\ \text{mA}\) (valeurs efficaces).<br>1) Calculer R.<br>2) Calculer le facteur de qualité \(Q = L\omega_0/R\) et la bande passante.<br>3) Calculer la puissance consommée.`,
    s: TX`1) \(R = \dfrac{U}{I_0} = 100\ \Omega\).<br>2) \(\omega_0 = 2\pi\times503 \approx 3160\ \text{rad/s}\) ; \(Q \approx \dfrac{0{,}05\times3160}{100} \approx 1{,}6\) ; \(\Delta N = \dfrac{N_0}{Q} \approx 318\ \text{Hz}\).<br>3) \(P = UI_0 = 0{,}36\ \text{W}\) (\(\cos\varphi = 1\)).` },
  { d: 2, t: 'Courbe de résonance', fig: cfig({ w: 420, h: 220, x1: 1000, xs: 200, y1: 60, ys: 10, xl: 'N (Hz)', yl: 'I (mA)', f: N => N < 5 ? 0 : 50 / Math.sqrt(1 + 16 * (N / 500 - 500 / N) ** 2), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(35.4)}" x2="${X(1000)}" y2="${Y(35.4)}" stroke="#12946a" stroke-dasharray="4 3"/>` }),
    q: TX`On a tracé la courbe de résonance d’un circuit RLC série (\(L = 0{,}10\ \text{H}\)).<br>1) Lire \(N_0\) et \(I_0\).<br>2) Déterminer graphiquement la bande passante (\(I \ge I_0/\sqrt2\)).<br>3) En déduire le facteur de qualité et R.`,
    s: TX`1) \(N_0 = 500\ \text{Hz}\) ; \(I_0 = 50\ \text{mA}\).<br>2) \(I_0/\sqrt2 \approx 35\ \text{mA}\) : de 442 Hz à 567 Hz environ, \(\Delta N \approx 125\ \text{Hz}\).<br>3) \(Q = \dfrac{500}{125} = 4\) ; \(R = 2\pi L\Delta N \approx 79\ \Omega\).` },
  { d: 3, t: 'Hors résonance', fig: SVG(300, 100, `<text x="150" y="40" text-anchor="middle" font-size="14">R = 100 Ω ; L = 0,10 H ; C = 1,0 µF</text><text x="150" y="70" text-anchor="middle" font-size="14">N = 300 Hz ; U = 5,0 V</text>`),
    q: TX`Un circuit RLC série est alimenté à 300 Hz sous 5,0 V (efficace).<br>1) Calculer \(L\omega\) et \(1/(C\omega)\).<br>2) Calculer Z, I et φ. Le circuit est-il inductif ou capacitif ?<br>3) Calculer la puissance moyenne.`,
    s: TX`1) \(\omega \approx 1885\ \text{rad/s}\) ; \(L\omega \approx 189\ \Omega\) ; \(\dfrac{1}{C\omega} \approx 531\ \Omega\).<br>2) \(Z = \sqrt{100^2 + 342^2} \approx 356\ \Omega\) ; \(I \approx 14\ \text{mA}\) ; \(\tan\varphi = -3{,}42\), \(\varphi \approx -74°\) : capacitif.<br>3) \(P = RI^2 \approx 2{,}0\times10^{-2}\ \text{W}\).` },
]);

addExos('2b-ondes-em', [
  { d: 1, t: 'Antenne de téléphone', fig: SVG(220, 180, `<rect x="70" y="40" width="80" height="130" rx="14" fill="#14213d"/><rect x="80" y="54" width="60" height="90" fill="#6aa5ff"/><line x1="140" y1="40" x2="140" y2="10" stroke="#5b6577" stroke-width="3"/>`),
    q: TX`Un téléphone utilise des ondes de fréquence 900 MHz.<br>1) Calculer leur longueur d’onde dans l’air.<br>2) La longueur d’une antenne simple est d’environ λ/2. Calculer cette longueur.<br>3) Ces ondes appartiennent-elles au domaine visible ?`,
    s: TX`1) \(\lambda = \dfrac{3\times10^{8}}{9\times10^{8}} \approx 0{,}33\ \text{m}\).<br>2) Environ 17 cm (en pratique, l’antenne est intégrée et repliée).<br>3) Non : ce sont des micro-ondes.` },
  { d: 2, t: 'Station de radio AM', fig: SVG(240, 200, `<line x1="120" y1="190" x2="120" y2="20" stroke="#14213d" stroke-width="4"/><line x1="80" y1="190" x2="120" y2="40" stroke="#5b6577"/><line x1="160" y1="190" x2="120" y2="40" stroke="#5b6577"/><path d="M140 40 q20 -20 40 0" fill="none" stroke="#d93a4a" stroke-width="2"/><path d="M150 30 q30 -30 60 0" fill="none" stroke="#d93a4a" stroke-width="2"/>`),
    q: TX`Une station émet sur une porteuse de 1,0 MHz un signal sonore de 1,0 kHz.<br>1) Calculer la longueur d’onde de la porteuse et celle d’une onde électromagnétique de 1,0 kHz.<br>2) Pourquoi ne transmet-on pas directement le signal de 1 kHz ?<br>3) La condition \(F_p \gg f_s\) est-elle respectée ?`,
    s: TX`1) 300 m ; 300 km.<br>2) Il faudrait une antenne gigantesque, et toutes les stations se mélangeraient.<br>3) Oui : \(F_p = 1000\,f_s\).` },
  { d: 3, t: 'Liaison par satellite', fig: SVG(360, 180, ball(70, 140, 40, '#1f6fe0', 'Terre') + `<rect x="270" y="20" width="30" height="16" fill="#d98200"/><line x1="90" y1="110" x2="275" y2="36" stroke="#d93a4a" stroke-dasharray="5 4"/><text x="200" y="60" font-size="11">36 000 km</text>`),
    q: TX`Un signal téléphonique passe par un satellite géostationnaire (altitude 36 000 km) : il monte vers le satellite puis redescend.<br>1) Calculer la durée de propagation aller-retour (on prend la distance égale à l’altitude).<br>2) Une conversation subit-elle un retard perceptible ?`,
    s: TX`1) \(\Delta t = \dfrac{2\times3{,}6\times10^{7}}{3\times10^{8}} = 0{,}24\ \text{s}\).<br>2) Oui : environ un quart de seconde (un demi-seconde pour une question et sa réponse).` },
  { d: 1, t: 'Classer des ondes', fig: TBL(['onde', 'fréquence'], [['radio FM', '100 MHz'], ['four à micro-ondes', '2,45 GHz'], ['lumière verte', '6×10¹⁴ Hz'], ['rayons X', '3×10¹⁸ Hz']], 360),
    q: TX`1) Calculer la longueur d’onde de chaque onde du tableau.<br>2) Classer ces ondes par longueur d’onde croissante.`,
    s: TX`1) FM : 3,0 m ; micro-ondes : 12 cm ; vert : 500 nm ; X : 0,1 nm.<br>2) X < lumière verte < micro-ondes < radio FM.` },
]);

addExos('2b-modulation', [
  { d: 1, t: 'Taux de modulation sur un oscillogramme', fig: SVG(460, 170, `<line x1="20" y1="85" x2="440" y2="85" stroke="#9aa6bf"/><polyline points="${Array.from({ length: 421 }, (_, i) => (20 + i) + ',' + (85 - 15 * (4 + 2 * Math.cos(2 * Math.PI * i / 210)) * Math.cos(2 * Math.PI * i / 12)).toFixed(1)).join(' ')}" fill="none" stroke="#1f6fe0" stroke-width="1.2"/><text x="10" y="16" font-size="11">1 div = 1 V (une division = 15 px)</text>`),
    q: TX`L’enveloppe supérieure du signal modulé varie entre \(U_{min} = 2{,}0\ \text{V}\) et \(U_{max} = 6{,}0\ \text{V}\).<br>1) Calculer le taux de modulation.<br>2) La modulation est-elle de bonne qualité ?`,
    s: TX`1) \(m = \dfrac{6 - 2}{6 + 2} = 0{,}50\).<br>2) Oui : \(m < 1\).` },
  { d: 2, t: 'Spectre d’un signal modulé', fig: SVG(400, 160, `<line x1="30" y1="130" x2="380" y2="130" stroke="#5b6577"/><text x="360" y="150" font-size="11">f (kHz)</text>${[[150, 40], [200, 100], [250, 40]].map(([x, h]) => `<line x1="${x}" y1="130" x2="${x}" y2="${130 - h}" stroke="#1f6fe0" stroke-width="5"/>`).join('')}<text x="140" y="148" font-size="11">?</text><text x="194" y="148" font-size="11">200</text><text x="244" y="148" font-size="11">?</text>`),
    q: TX`Une porteuse de 200 kHz est modulée en amplitude par un son pur de 5 kHz.<br>1) Donner les fréquences des trois raies du spectre.<br>2) Quelle largeur de bande occupe l’émission ?<br>3) Deux stations voisines doivent avoir des porteuses séparées d’au moins combien ?`,
    s: TX`1) 195 kHz, 200 kHz et 205 kHz.<br>2) 10 kHz.<br>3) 10 kHz (pour que leurs bandes ne se recouvrent pas).` },
  { d: 2, t: 'Dimensionner le détecteur d’enveloppe', fig: SVG(400, 140, `<polygon points="80,60 80,90 104,75" fill="#14213d"/><line x1="104" y1="60" x2="104" y2="90" stroke="#14213d" stroke-width="3"/>` + W_('30,75 80,75') + W_('104,75 300,75') + RES(200, 105, 'R', 1).replace('x="216"', 'x="214"') + `<line x1="270" y1="75" x2="270" y2="98" stroke="#14213d" stroke-width="2"/><line x1="258" y1="98" x2="282" y2="98" stroke="#14213d" stroke-width="3"/><line x1="258" y1="106" x2="282" y2="106" stroke="#14213d" stroke-width="3"/><text x="288" y="106">C</text>`),
    q: TX`Le signal à démoduler a \(F_p = 100\ \text{kHz}\) et \(f_s = 2{,}0\ \text{kHz}\). On choisit \(R = 10\ \text{k}\Omega\).<br>1) Écrire la condition sur RC.<br>2) Parmi 1 nF, 10 nF et 1 µF, quelle capacité convient ?`,
    s: TX`1) \(T_p = 10\ \mu\text{s} \ll RC < T_s = 500\ \mu\text{s}\).<br>2) 10 nF : \(RC = 100\ \mu\text{s}\) (1 nF donne 10 µs, trop petit ; 1 µF donne 10 ms, trop grand).` },
  { d: 3, t: 'Accorder le récepteur', fig: SVG(300, 140, `<path d="M80 30 q14 8 0 16 q14 8 0 16 q14 8 0 16 q14 8 0 16" fill="none" stroke="#d98200" stroke-width="3"/><line x1="170" y1="60" x2="200" y2="60" stroke="#14213d" stroke-width="3"/><line x1="170" y1="72" x2="200" y2="72" stroke="#14213d" stroke-width="3"/><line x1="160" y1="90" x2="210" y2="40" stroke="#d93a4a" stroke-width="2"/><text x="60" y="120">L = 1 mH</text><text x="160" y="120">C réglable</text>`),
    q: TX`Le circuit d’accord d’un récepteur comporte une bobine de 1,0 mH et un condensateur réglable.<br>1) Quelle capacité faut-il pour capter une station de 500 kHz ?<br>2) Pour capter une station de fréquence plus élevée, faut-il augmenter ou diminuer C ?`,
    s: TX`1) \(C = \dfrac{1}{4\pi^2F_p^2L} = \dfrac{1}{4\pi^2\times(5\times10^{5})^2\times10^{-3}} \approx 1{,}0\times10^{-10}\ \text{F} = 100\ \text{pF}\).<br>2) Diminuer C (\(F_p \propto 1/\sqrt C\)).` },
]);

/* ===== Mécanique ===== */
addExos('2b-newton', [
  { d: 1, t: 'Exploiter v(t)', fig: cfig({ w: 420, h: 220, x1: 10, xs: 2, y1: 25, ys: 5, xl: 't (s)', yl: 'v (m/s)', f: t => 2 * t + 2 }),
    q: TX`Une voiture de 1000 kg roule en ligne droite ; la courbe donne sa vitesse.<br>1) Quelle est la nature du mouvement ? Calculer l’accélération.<br>2) Calculer la somme des forces appliquées.<br>3) Calculer la distance parcourue entre 0 et 10 s.`,
    s: TX`1) Rectiligne uniformément accéléré : \(a = \dfrac{22 - 2}{10} = 2{,}0\ \text{m/s}^2\).<br>2) \(\sum F = ma = 2{,}0\times10^{3}\ \text{N}\).<br>3) \(d = \tfrac12at^2 + v_0t = 100 + 20 = 120\ \text{m}\).` },
  { d: 2, t: 'Solide tiré avec frottement', fig: SVG(420, 130, ARW('n6') + `<line x1="20" y1="100" x2="400" y2="100" stroke="#5b6577" stroke-width="2"/><rect x="150" y="60" width="70" height="40" fill="#d98200"/>${VEC(220, 80, 300, 80, 'F', '#d93a4a', 'n6')}${VEC(150, 96, 100, 96, 'f', '#12946a', 'n6')}`),
    q: TX`Un solide de 4,0 kg est tiré sur un plan horizontal par une force horizontale \(F = 20\ \text{N}\) ; une force de frottement constante \(f = 4{,}0\ \text{N}\) s’oppose au mouvement. Il part du repos.<br>1) Appliquer la 2ᵉ loi de Newton et calculer a.<br>2) Calculer la vitesse et la distance parcourue au bout de 3,0 s.<br>3) On supprime F à cet instant. Au bout de combien de temps le solide s’arrête-t-il ?`,
    s: TX`1) \(F - f = ma \Rightarrow a = \dfrac{16}{4} = 4{,}0\ \text{m/s}^2\).<br>2) \(v = 12\ \text{m/s}\) ; \(d = 18\ \text{m}\).<br>3) \(a' = -\dfrac{f}{m} = -1{,}0\ \text{m/s}^2\) : arrêt au bout de 12 s.` },
  { d: 3, t: 'Voiture dans un virage', fig: SVG(300, 200, `<path d="M40 190 A 150 150 0 0 1 260 40" fill="none" stroke="#5b6577" stroke-width="18"/><path d="M40 190 A 150 150 0 0 1 260 40" fill="none" stroke="#fff" stroke-width="2" stroke-dasharray="8 8"/><rect x="104" y="80" width="30" height="16" fill="#d93a4a" transform="rotate(-40 119 88)"/><text x="190" y="190" font-size="11">R = 100 m</text>`),
    q: TX`Une voiture de 1000 kg aborde à 72 km/h un virage circulaire de rayon 100 m, à vitesse constante.<br>1) Le mouvement est-il accéléré ? Calculer l’accélération et préciser sa direction.<br>2) Quelle force horizontale doit exercer la route sur la voiture ?<br>3) Si cette force ne peut dépasser 6000 N, quelle est la vitesse maximale dans ce virage ?`,
    s: TX`1) Oui (la direction de \(\vec v\) change) : \(a_n = \dfrac{v^2}{R} = \dfrac{400}{100} = 4{,}0\ \text{m/s}^2\), vers le centre.<br>2) \(F = ma_n = 4{,}0\times10^{3}\ \text{N}\), vers le centre.<br>3) \(v_{max} = \sqrt{\dfrac{6000\times100}{1000}} \approx 24{,}5\ \text{m/s} \approx 88\ \text{km/h}\).` },
]);

addExos('2b-chute', [
  { d: 1, t: 'Lancer vertical', fig: SVG(200, 200, ARW('c5', '#1f6fe0') + `<line x1="20" y1="185" x2="180" y2="185" stroke="#5b6577" stroke-width="2"/><circle cx="100" cy="170" r="8" fill="#d98200"/><line x1="100" y1="160" x2="100" y2="50" stroke="#1f6fe0" stroke-width="2" marker-end="url(#c5)"/><text x="108" y="110">v₀ = 15 m/s</text>`),
    q: TX`On lance une balle verticalement vers le haut à 15 m/s ; on néglige l’air ; \(g = 10\ \text{m/s}^2\). Axe Oz vers le haut, origine au point de lancement.<br>1) Écrire \(v(t)\) et \(z(t)\).<br>2) Calculer la date et l’altitude du sommet.<br>3) À quelle date la balle revient-elle au point de départ ?`,
    s: TX`1) \(v = -10t + 15\) ; \(z = -5t^2 + 15t\).<br>2) \(v = 0\) à \(t = 1{,}5\ \text{s}\) ; \(z = 11{,}25\ \text{m}\).<br>3) \(z = 0\) à \(t = 3{,}0\ \text{s}\).` },
  { d: 2, t: 'Vitesse limite et temps caractéristique', fig: cfig({ w: 420, h: 220, x1: 1, xs: 0.2, y1: 2.5, ys: 0.5, xl: 't (s)', yl: 'v (m/s)', f: t => 2 * (1 - Math.exp(-t / 0.2)), fmtx: x => String(x).replace('.', ','), fmty: y => String(y).replace('.', ','), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(0.2)}" y2="${Y(2)}" stroke="#d93a4a" stroke-dasharray="5 3"/>` }),
    q: TX`La courbe donne la vitesse d’une bille qui tombe dans un liquide. On modélise \(\dfrac{dv}{dt} = A - Bv\).<br>1) Déterminer \(v_\ell\) et τ.<br>2) En déduire A (pente à l’origine) et B.<br>3) Comparer A à g. Que traduit la différence ?`,
    s: TX`1) \(v_\ell = 2{,}0\ \text{m/s}\) ; \(\tau = 0{,}20\ \text{s}\).<br>2) \(A = \dfrac{v_\ell}{\tau} = 10\ \text{m/s}^2\) ; \(B = \dfrac{A}{v_\ell} = 5{,}0\ \text{s}^{-1}\).<br>3) A ≈ g : la poussée d’Archimède est ici négligeable (bille très dense).` },
  { d: 3, t: 'Appliquer la méthode d’Euler', fig: TBL(['t (s)', '0', '0,1', '0,2', '0,3'], [['v (m/s)', '0', '?', '?', '?'], ['a (m/s²)', '9,8', '?', '?', '—']], 440),
    q: TX`Une goutte de pluie vérifie \(\dfrac{dv}{dt} = 9{,}8 - 0{,}50\,v\) (SI). Elle part du repos.<br>1) Calculer sa vitesse limite.<br>2) Compléter le tableau avec la méthode d’Euler (pas Δt = 0,1 s).<br>3) Comment améliorer la précision ?`,
    s: TX`1) \(v_\ell = \dfrac{9{,}8}{0{,}50} = 19{,}6\ \text{m/s}\).<br>2) \(v_1 = 0{,}98\) ; \(a_1 = 9{,}31\) ; \(v_2 \approx 1{,}91\) ; \(a_2 \approx 8{,}84\) ; \(v_3 \approx 2{,}80\ \text{m/s}\).<br>3) Diminuer le pas Δt.` },
]);

addExos('2b-plans', [
  { d: 1, t: 'Bille qui quitte une table', fig: SVG(400, 200, `<rect x="20" y="60" width="140" height="10" fill="#d98200"/><rect x="140" y="70" width="10" height="120" fill="#d98200"/><line x1="10" y1="190" x2="390" y2="190" stroke="#5b6577" stroke-width="2"/><circle cx="155" cy="54" r="7" fill="#1f6fe0"/><path d="M160 56 Q 230 60 300 190" fill="none" stroke="#1f6fe0" stroke-dasharray="5 4"/><text x="160" y="140" font-size="11">h = 1,25 m</text>`),
    q: TX`Une bille quitte le bord d’une table de hauteur 1,25 m avec une vitesse horizontale de 3,0 m/s. \(g = 10\ \text{m/s}^2\).<br>1) Écrire les équations horaires (origine au bord de la table, Oy vers le bas).<br>2) Calculer la durée de chute.<br>3) À quelle distance du pied de la table touche-t-elle le sol ?`,
    s: TX`1) \(x = 3{,}0\,t\) ; \(y = 5\,t^2\).<br>2) \(5t^2 = 1{,}25 \Rightarrow t = 0{,}50\ \text{s}\).<br>3) \(x = 1{,}5\ \text{m}\).` },
  { d: 2, t: 'Lancer de javelot', fig: SVG(440, 190, `<line x1="20" y1="170" x2="420" y2="170" stroke="#5b6577"/><path d="M30 170 Q 220 -20 410 170" fill="none" stroke="#1f6fe0" stroke-width="3" stroke-dasharray="6 4"/><line x1="30" y1="170" x2="90" y2="120" stroke="#d93a4a" stroke-width="3"/><text x="52" y="164">40°</text>`),
    q: TX`Un javelot est lancé avec \(v_0 = 25\ \text{m/s}\) sous un angle de 40° ; on assimile son point de départ au sol et on néglige l’air. \(g = 9{,}8\ \text{m/s}^2\).<br>1) Calculer la portée.<br>2) Calculer la flèche.<br>3) Quel angle donnerait la portée maximale ? Calculer cette portée.`,
    s: TX`1) \(x_P = \dfrac{625\sin80°}{9{,}8} \approx 62{,}8\ \text{m}\).<br>2) \(y_S = \dfrac{625\sin^240°}{2\times9{,}8} \approx 13{,}2\ \text{m}\).<br>3) 45° : \(x_{P,max} = \dfrac{625}{9{,}8} \approx 63{,}8\ \text{m}\).` },
  { d: 3, t: 'Spectrographe de masse', fig: SVG(420, 220, `<rect x="20" y="20" width="380" height="190" fill="#eaf1fd" stroke="#9aa6bf"/>${[0, 1, 2, 3, 4, 5, 6].map(i => [0, 1, 2].map(j => `<text x="${60 + i * 50}" y="${60 + j * 50}" fill="#1f6fe0">⊙</text>`).join('')).join('')}<path d="M210 210 A 80 80 0 0 1 50 210" fill="none" stroke="#d93a4a" stroke-width="2.5"/><path d="M210 210 A 88 88 0 0 1 34 210" fill="none" stroke="#d98200" stroke-width="2.5"/><text x="214" y="204" font-size="11">entrée des ions</text>`),
    q: TX`Des ions \({}^{20}\text{Ne}^+\) et \({}^{22}\text{Ne}^+\) (\(m = A\times1{,}66\times10^{-27}\ \text{kg}\), \(q = e\)), accélérés sans vitesse initiale sous \(U = 1000\ \text{V}\), entrent dans un champ magnétique uniforme \(B = 0{,}10\ \text{T}\) perpendiculaire à leur vitesse.<br>1) Exprimer la vitesse à l’entrée du champ en fonction de m, q, U.<br>2) Montrer que \(R = \dfrac{1}{B}\sqrt{\dfrac{2mU}{q}}\) et calculer R pour chaque isotope.<br>3) Après un demi-tour, quelle distance sépare les points d’impact ?`,
    s: TX`1) \(\tfrac12mv^2 = qU \Rightarrow v = \sqrt{\dfrac{2qU}{m}}\).<br>2) \(R = \dfrac{mv}{qB}\) d’où la relation ; \(R_{20} \approx 0{,}204\ \text{m}\) ; \(R_{22} = R_{20}\sqrt{1{,}1} \approx 0{,}214\ \text{m}\).<br>3) \(2(R_{22} - R_{20}) \approx 2{,}0\ \text{cm}\).` },
]);

addExos('2b-satellites', [
  { d: 1, t: 'La Station spatiale internationale', fig: SVG(300, 220, ball(150, 110, 60, '#1f6fe0', 'Terre') + `<circle cx="150" cy="110" r="80" fill="none" stroke="#9aa6bf" stroke-dasharray="5 4"/><rect x="220" y="64" width="22" height="10" fill="#d98200"/><text x="214" y="56" font-size="11">ISS</text>`),
    q: TX`L’ISS est en orbite circulaire à 400 km d’altitude. \(R_T = 6400\ \text{km}\), \(M_T = 6{,}0\times10^{24}\ \text{kg}\), \(G = 6{,}67\times10^{-11}\) SI.<br>1) Calculer sa vitesse.<br>2) Calculer sa période en minutes.<br>3) Combien de tours effectue-t-elle par jour ?`,
    s: TX`1) \(r = 6{,}8\times10^{6}\ \text{m}\) ; \(v = \sqrt{\dfrac{GM_T}{r}} \approx 7{,}7\times10^{3}\ \text{m/s}\).<br>2) \(T = \dfrac{2\pi r}{v} \approx 5{,}6\times10^{3}\ \text{s} \approx 93\ \text{min}\).<br>3) \(\dfrac{1440}{93} \approx 15{,}5\) tours.` },
  { d: 2, t: 'La période de Mars', fig: SVG(360, 220, ball(180, 110, 18, '#ffb23e', '') + `<circle cx="180" cy="110" r="60" fill="none" stroke="#1f6fe0" stroke-dasharray="4 3"/><circle cx="240" cy="110" r="6" fill="#1f6fe0"/><text x="246" y="104" font-size="11">Terre (1 UA)</text><circle cx="180" cy="110" r="92" fill="none" stroke="#d93a4a" stroke-dasharray="4 3"/><circle cx="180" cy="18" r="5" fill="#d93a4a"/><text x="188" y="16" font-size="11">Mars (1,52 UA)</text>`),
    q: TX`La Terre tourne autour du Soleil en 1 an à 1,00 UA ; Mars, à 1,52 UA (orbites supposées circulaires).<br>1) Énoncer la troisième loi de Kepler.<br>2) Calculer la période de révolution de Mars.`,
    s: TX`1) \(\dfrac{T^2}{r^3}\) est la même pour toutes les planètes du Soleil.<br>2) \(T_M = 1\times1{,}52^{3/2} \approx 1{,}87\ \text{an}\).` },
  { d: 3, t: '« Peser » la Terre grâce à la Lune', fig: SVG(360, 200, ball(100, 100, 40, '#1f6fe0', 'Terre') + ball(300, 100, 12, '#9aa6bf', '') + `<line x1="140" y1="100" x2="288" y2="100" stroke="#9aa6bf" stroke-dasharray="4 3"/><text x="180" y="92" font-size="11">r = 3,84×10⁵ km</text><text x="284" y="128" font-size="11">Lune</text>`),
    q: TX`La Lune décrit une orbite pratiquement circulaire de rayon \(3{,}84\times10^{5}\ \text{km}\) en 27,3 jours.<br>1) Établir l’expression de la période en fonction de r, G et \(M_T\).<br>2) En déduire la masse de la Terre.`,
    s: TX`1) \(\dfrac{v^2}{r} = \dfrac{GM_T}{r^2}\) et \(v = \dfrac{2\pi r}{T}\) : \(T^2 = \dfrac{4\pi^2r^3}{GM_T}\).<br>2) \(M_T = \dfrac{4\pi^2r^3}{GT^2} = \dfrac{4\pi^2(3{,}84\times10^{8})^3}{6{,}67\times10^{-11}\times(2{,}36\times10^{6})^2} \approx 6{,}0\times10^{24}\ \text{kg}\).` },
]);

addExos('2b-rotation', [
  { d: 1, t: 'Démarrage d’un disque', fig: SVG(220, 180, `<circle cx="110" cy="90" r="70" fill="#9aa6bf" stroke="#14213d" stroke-width="3"/><circle cx="110" cy="90" r="6" fill="#14213d"/><path d="M60 40 A70 70 0 0 1 160 40" fill="none" stroke="#d93a4a" stroke-width="2"/>`),
    q: TX`Un disque part du repos avec une accélération angulaire constante \(\ddot\theta = 2{,}0\ \text{rad/s}^2\).<br>1) Calculer sa vitesse angulaire à \(t = 5{,}0\ \text{s}\).<br>2) Calculer l’angle balayé et le nombre de tours.<br>3) Calculer la vitesse d’un point à 10 cm de l’axe à cet instant.`,
    s: TX`1) \(\dot\theta = 10\ \text{rad/s}\).<br>2) \(\theta = \tfrac12\times2\times25 = 25\ \text{rad}\), soit environ 4 tours.<br>3) \(v = 0{,}10\times10 = 1{,}0\ \text{m/s}\).` },
  { d: 2, t: 'Couple moteur et frottements', fig: SVG(300, 140, `<rect x="40" y="40" width="100" height="60" rx="10" fill="#5b6577"/><rect x="140" y="64" width="60" height="12" fill="#9aa6bf"/><circle cx="220" cy="70" r="36" fill="#d98200" opacity=".6" stroke="#14213d"/>`),
    q: TX`Un moteur exerce un couple de moment 0,40 N·m sur un volant (\(J_\Delta = 0{,}020\ \text{kg·m}^2\)) ; un couple de frottement de 0,10 N·m s’y oppose.<br>1) Appliquer la RFD en rotation et calculer \(\ddot\theta\).<br>2) Combien de temps faut-il pour atteindre 300 rad/s ?<br>3) On coupe le moteur : calculer la nouvelle accélération angulaire.`,
    s: TX`1) \(0{,}40 - 0{,}10 = 0{,}020\,\ddot\theta \Rightarrow \ddot\theta = 15\ \text{rad/s}^2\).<br>2) \(t = 20\ \text{s}\).<br>3) \(\ddot\theta = -\dfrac{0{,}10}{0{,}020} = -5{,}0\ \text{rad/s}^2\).` },
  { d: 2, t: 'Exploiter ω(t)', fig: cfig({ w: 420, h: 220, x1: 5, xs: 1, y1: 24, ys: 4, xl: 't (s)', yl: 'θ̇ (rad/s)', f: t => 4 * t }),
    q: TX`La courbe donne la vitesse angulaire d’un cylindre (\(J_\Delta = 0{,}050\ \text{kg·m}^2\)).<br>1) Déterminer l’accélération angulaire.<br>2) Calculer la somme des moments des forces appliquées.<br>3) Calculer l’angle balayé entre 0 et 5 s.`,
    s: TX`1) \(\ddot\theta = 4{,}0\ \text{rad/s}^2\).<br>2) \(\sum\mathcal M = J\ddot\theta = 0{,}20\ \text{N·m}\).<br>3) \(\theta = \tfrac12\times4\times25 = 50\ \text{rad}\).` },
  { d: 3, t: 'Poulie et masse', fig: SVG(260, 220, `<line x1="40" y1="10" x2="220" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="130" y1="10" x2="130" y2="50" stroke="#5b6577" stroke-width="3"/><circle cx="130" cy="70" r="30" fill="#9aa6bf" stroke="#14213d" stroke-width="2"/><line x1="160" y1="70" x2="160" y2="160" stroke="#14213d" stroke-width="2"/><rect x="145" y="160" width="30" height="30" fill="#d98200"/>`),
    q: TX`Une masse \(m = 0{,}50\ \text{kg}\) est suspendue à un fil enroulé sur une poulie (\(r = 0{,}10\ \text{m}\), \(J_\Delta = 5{,}0\times10^{-3}\ \text{kg·m}^2\)). \(g = 10\ \text{m/s}^2\).<br>1) Appliquer la 2ᵉ loi à la masse et la RFD à la poulie.<br>2) Montrer que \(a = \dfrac{mg}{m + J/r^2}\) et la calculer.<br>3) Calculer la tension du fil.`,
    s: TX`1) \(mg - T = ma\) ; \(Tr = J\ddot\theta\) avec \(a = r\ddot\theta\).<br>2) \(T = \dfrac{Ja}{r^2}\) donc \(mg = a\Big(m + \dfrac{J}{r^2}\Big)\) ; \(a = \dfrac{5}{0{,}5 + 0{,}5} = 5{,}0\ \text{m/s}^2\).<br>3) \(T = m(g - a) = 2{,}5\ \text{N}\).` },
]);

addExos('2b-oscillants', [
  { d: 1, t: 'Lire un enregistrement x(t)', fig: cfig({ w: 420, h: 220, x1: 1.5, xs: 0.25, y0: -4, y1: 4, ys: 1, xl: 't (s)', yl: 'x (cm)', f: t => 3 * Math.cos(4 * Math.PI * t), fmtx: x => String(x).replace('.', ',') }),
    q: TX`La courbe donne la position d’un solide (\(m = 0{,}20\ \text{kg}\)) attaché à un ressort horizontal.<br>1) Lire l’amplitude et la période propre.<br>2) Calculer la raideur k.<br>3) Écrire l’équation horaire \(x(t)\).`,
    s: TX`1) \(X_m = 3{,}0\ \text{cm}\) ; \(T_0 = 0{,}50\ \text{s}\).<br>2) \(k = \dfrac{4\pi^2m}{T_0^2} \approx 32\ \text{N/m}\).<br>3) \(x(0) = X_m\) donc \(\varphi = 0\) : \(x = 0{,}030\cos(4\pi t)\) (m).` },
  { d: 2, t: 'Pendule sur la Lune', fig: SVG(220, 200, `<line x1="40" y1="10" x2="180" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="110" y1="10" x2="140" y2="160" stroke="#14213d" stroke-width="2"/><circle cx="140" cy="160" r="12" fill="#d98200"/><text x="128" y="96" font-size="11">ℓ = 1,0 m</text>`),
    q: TX`Un pendule simple de longueur 1,0 m effectue de petites oscillations.<br>1) Calculer sa période sur la Terre (\(g = 9{,}8\ \text{m/s}^2\)).<br>2) Calculer sa période sur la Lune (\(g = 1{,}62\ \text{m/s}^2\)).<br>3) Quelle longueur faudrait-il sur la Terre pour une période de 1,0 s ?`,
    s: TX`1) \(T_0 = 2\pi\sqrt{\dfrac{1}{9{,}8}} \approx 2{,}0\ \text{s}\).<br>2) \(T_0 \approx 4{,}9\ \text{s}\).<br>3) \(\ell = \dfrac{gT^2}{4\pi^2} \approx 0{,}25\ \text{m}\).` },
  { d: 3, t: 'Constante de torsion d’un fil', fig: SVG(260, 200, `<line x1="60" y1="10" x2="200" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="130" y1="10" x2="130" y2="120" stroke="#14213d" stroke-width="2"/><rect x="40" y="118" width="180" height="8" fill="#d98200"/><text x="70" y="150" font-size="11">tige : m = 0,30 kg ; L = 40 cm</text>`),
    q: TX`Une tige homogène (\(m = 0{,}30\ \text{kg}\), \(L = 40\ \text{cm}\)) est suspendue en son milieu à un fil de torsion. Elle oscille avec une période de 2,0 s.<br>1) Calculer son moment d’inertie (\(J = \tfrac{1}{12}mL^2\)).<br>2) Calculer la constante de torsion C.<br>3) Que devient la période si on remplace la tige par une tige deux fois plus longue de même masse ?`,
    s: TX`1) \(J = \dfrac{0{,}30\times0{,}16}{12} = 4{,}0\times10^{-3}\ \text{kg·m}^2\).<br>2) \(C = \dfrac{4\pi^2J}{T_0^2} \approx 3{,}9\times10^{-2}\ \text{N·m/rad}\).<br>3) J est multiplié par 4, donc \(T_0\) par 2 : 4,0 s.` },
  { d: 2, t: 'Conditions initiales', fig: SVG(440, 110, `<rect x="10" y="20" width="12" height="70" fill="#5b6577"/><line x1="10" y1="90" x2="430" y2="90" stroke="#5b6577" stroke-width="2"/><polyline points="22,60 40,60 50,45 70,75 90,45 110,75 130,45 150,75 170,45 190,60 210,60" fill="none" stroke="#14213d" stroke-width="2"/><rect x="210" y="40" width="50" height="40" fill="#d98200"/>`),
    q: TX`Un pendule élastique (\(m = 0{,}25\ \text{kg}\), \(k = 25\ \text{N/m}\)) passe par la position d’équilibre à \(t = 0\) en se déplaçant dans le sens positif avec la vitesse 0,40 m/s.<br>1) Calculer \(T_0\).<br>2) Déterminer \(X_m\) (utiliser \(V_m = \dfrac{2\pi}{T_0}X_m\)).<br>3) Déterminer φ et écrire \(x(t)\).`,
    s: TX`1) \(T_0 = 2\pi\sqrt{0{,}01} \approx 0{,}63\ \text{s}\) ; \(\omega_0 = 10\ \text{rad/s}\).<br>2) \(X_m = \dfrac{V_m}{\omega_0} = 0{,}040\ \text{m}\).<br>3) \(x(0) = 0\) et \(\dot x(0) > 0\) : \(\varphi = -\dfrac{\pi}{2}\) ; \(x = 0{,}040\cos(10t - \pi/2)\).` },
]);

addExos('2b-energie', [
  { d: 1, t: 'Énergie d’un oscillateur', fig: SVG(440, 110, `<rect x="10" y="20" width="12" height="70" fill="#5b6577"/><line x1="10" y1="90" x2="430" y2="90" stroke="#5b6577" stroke-width="2"/><polyline points="22,60 40,60 50,45 70,75 90,45 110,75 130,45 150,75 170,45 190,60 210,60" fill="none" stroke="#14213d" stroke-width="2"/><rect x="210" y="40" width="50" height="40" fill="#d98200"/>`),
    q: TX`Un pendule élastique horizontal (\(k = 40\ \text{N/m}\), \(m = 0{,}10\ \text{kg}\)) oscille sans frottement avec l’amplitude 5,0 cm.<br>1) Calculer son énergie mécanique.<br>2) Calculer sa vitesse maximale.<br>3) Calculer sa vitesse quand \(x = 3{,}0\ \text{cm}\).`,
    s: TX`1) \(E_m = \tfrac12\times40\times0{,}05^2 = 5{,}0\times10^{-2}\ \text{J}\).<br>2) \(V_m = \sqrt{\dfrac{2E_m}{m}} = 1{,}0\ \text{m/s}\).<br>3) \(\tfrac12mv^2 = E_m - \tfrac12kx^2 = 0{,}05 - 0{,}018 = 0{,}032\ \text{J}\) : \(v = 0{,}80\ \text{m/s}\).` },
  { d: 2, t: 'Diagramme d’énergie', fig: cfig({ w: 420, h: 220, x1: 0.06, xs: 0.01, y1: 0.1, ys: 0.02, xl: 'x (m)', yl: 'E (J)', f: x => 25 * x * x, fmtx: x => String(x).replace('.', ','), fmty: y => String(+y.toFixed(2)).replace('.', ','), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0.0625)}" x2="${X(0.05)}" y2="${Y(0.0625)}" stroke="#12946a" stroke-dasharray="5 4" stroke-width="2"/>` }),
    q: TX`On a tracé l’énergie potentielle élastique d’un pendule élastique en fonction de x (pour \(x \ge 0\)) ; la droite pointillée représente son énergie mécanique.<br>1) Déterminer k (lire un point).<br>2) Lire l’énergie mécanique et en déduire l’amplitude.<br>3) Quelle est l’énergie cinétique pour \(x = 0\) ?`,
    s: TX`1) \(E_{pe}(0{,}05) = 0{,}0625\ \text{J}\) : \(k = \dfrac{2\times0{,}0625}{0{,}05^2} = 50\ \text{N/m}\).<br>2) \(E_m = 0{,}0625\ \text{J}\), atteinte pour \(X_m = 5{,}0\ \text{cm}\).<br>3) \(E_c = E_m = 0{,}0625\ \text{J}\).` },
  { d: 2, t: 'Pendule de torsion', fig: SVG(260, 180, `<line x1="60" y1="10" x2="200" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="130" y1="10" x2="130" y2="110" stroke="#14213d" stroke-width="2"/><rect x="40" y="108" width="180" height="8" fill="#d98200"/>`),
    q: TX`Un pendule de torsion (\(C = 5{,}0\times10^{-2}\ \text{N·m/rad}\), \(J_\Delta = 2{,}0\times10^{-3}\ \text{kg·m}^2\)) est écarté de 0,50 rad puis lâché sans vitesse.<br>1) Calculer son énergie mécanique.<br>2) Calculer sa vitesse angulaire maximale.<br>3) Calculer sa période propre.`,
    s: TX`1) \(E_m = \tfrac12C\theta_m^2 = 6{,}25\times10^{-3}\ \text{J}\).<br>2) \(\dot\theta_{max} = \sqrt{\dfrac{2E_m}{J}} = 2{,}5\ \text{rad/s}\).<br>3) \(T_0 = 2\pi\sqrt{\dfrac{J}{C}} \approx 1{,}26\ \text{s}\).` },
  { d: 3, t: 'Pendule simple lâché à 60°', fig: SVG(240, 200, `<line x1="40" y1="10" x2="200" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="120" y1="10" x2="120" y2="160" stroke="#9aa6bf" stroke-dasharray="4 3"/><line x1="120" y1="10" x2="50" y2="130" stroke="#14213d" stroke-width="2"/><circle cx="50" cy="130" r="10" fill="#d98200"/><text x="96" y="60" font-size="11">60°</text>`),
    q: TX`Un pendule simple (\(m = 0{,}20\ \text{kg}\), \(\ell = 0{,}50\ \text{m}\)) est lâché sans vitesse d’un angle de 60°. On néglige les frottements ; \(g = 10\ \text{m/s}^2\). Référence de \(E_{pp}\) : position d’équilibre.<br>1) Calculer l’énergie potentielle initiale.<br>2) Calculer la vitesse au passage par la position d’équilibre.<br>3) Calculer la vitesse quand le fil fait 30° avec la verticale.`,
    s: TX`1) \(E_{pp} = mg\ell(1 - \cos60°) = 0{,}50\ \text{J}\).<br>2) \(v = \sqrt{2g\ell(1 - \cos60°)} = \sqrt5 \approx 2{,}2\ \text{m/s}\).<br>3) \(v = \sqrt{2g\ell(\cos30° - \cos60°)} \approx 1{,}9\ \text{m/s}\).` },
]);

addExos('2b-atome', [
  { d: 1, t: 'Niveaux d’énergie de l’hydrogène', fig: TBL(['n', '1', '2', '3', '4', '∞'], [['E_n (eV)', '?', '?', '?', '?', '0']], 440),
    q: TX`1) Compléter le tableau avec \(E_n = -\dfrac{13{,}6}{n^2}\) eV.<br>2) Que représente le niveau n = 1 ? le niveau ∞ ?<br>3) Calculer l’énergie d’ionisation depuis le niveau 2.`,
    s: TX`1) −13,6 ; −3,40 ; −1,51 ; −0,85 ; 0 eV.<br>2) n = 1 : état fondamental ; ∞ : atome ionisé.<br>3) 3,40 eV.` },
  { d: 2, t: 'Raie bleu-vert de Balmer', fig: SVG(400, 80, `<rect x="20" y="20" width="360" height="40" fill="#14213d"/><line x1="102" y1="20" x2="102" y2="60" stroke="#7a4fd6" stroke-width="3"/><line x1="138" y1="20" x2="138" y2="60" stroke="#5b4fd6" stroke-width="3"/><line x1="190" y1="20" x2="190" y2="60" stroke="#12a6a6" stroke-width="3"/><line x1="320" y1="20" x2="320" y2="60" stroke="#d93a4a" stroke-width="3"/>`),
    q: TX`Une raie du spectre de l’hydrogène correspond à la transition du niveau 4 vers le niveau 2. \(h = 6{,}63\times10^{-34}\ \text{J·s}\), \(c = 3{,}0\times10^{8}\ \text{m/s}\).<br>1) Calculer l’énergie du photon émis en eV puis en J.<br>2) Calculer sa longueur d’onde. Dans quel domaine se trouve-t-elle ?`,
    s: TX`1) \(\Delta E = 3{,}40 - 0{,}85 = 2{,}55\ \text{eV} \approx 4{,}08\times10^{-19}\ \text{J}\).<br>2) \(\lambda = \dfrac{hc}{\Delta E} \approx 4{,}87\times10^{-7}\ \text{m}\) : visible (bleu-vert).` },
  { d: 2, t: 'Une raie ultraviolette', fig: SVG(300, 100, `<text x="150" y="56" text-anchor="middle" font-size="16">n = 2 → n = 1</text>`),
    q: TX`1) Calculer l’énergie du photon émis lors de la transition 2 → 1.<br>2) Calculer sa longueur d’onde ; est-elle visible ?<br>3) Un atome dans l’état fondamental peut-il absorber un photon de 10,2 eV ? de 11 eV ?`,
    s: TX`1) \(\Delta E = 13{,}6 - 3{,}40 = 10{,}2\ \text{eV}\).<br>2) \(\lambda \approx 122\ \text{nm}\) : ultraviolet.<br>3) 10,2 eV : oui (passage au niveau 2) ; 11 eV : non (ne correspond à aucune différence de niveaux et ne suffit pas à l’ioniser).` },
  { d: 3, t: 'Absorption puis cascade', fig: SVG(300, 200, `${[[1, -13.6], [2, -3.4], [3, -1.51], [4, -0.85]].map(([n, E]) => { const y = 20 - E * 13; return `<line x1="40" y1="${y}" x2="200" y2="${y}" stroke="#14213d" stroke-width="2"/>${n <= 2 ? `<text x="208" y="${y + 4}" font-size="11">n = ${n}</text>` : ''}`; }).join('')}<text x="208" y="34" font-size="11">n = 3, 4</text>`),
    q: TX`Des atomes d’hydrogène dans l’état fondamental absorbent des photons de 12,75 eV.<br>1) Sur quel niveau se trouvent-ils ensuite ?<br>2) En se désexcitant, combien de raies différentes peuvent-ils émettre ? Les lister.<br>3) Calculer la longueur d’onde la plus grande.`,
    s: TX`1) \(E = -13{,}6 + 12{,}75 = -0{,}85\ \text{eV}\) : niveau 4.<br>2) Six raies : 4→3, 4→2, 4→1, 3→2, 3→1, 2→1.<br>3) La plus petite énergie (4→3 : 0,66 eV) : \(\lambda = \dfrac{1240}{0{,}66} \approx 1{,}9\ \mu\text{m}\) (infrarouge).` },
]);

/* ===== Chimie ===== */
const BEAKER = (txt, col) => SVG(240, 180, `<path d="M60 30 h120 v130 h-120 z" fill="${col || '#6aa5ff'}" opacity=".35" stroke="#14213d" stroke-width="2"/>${txt || ''}`);
addExos('2bc-lentes', [
  { d: 1, t: 'Eau oxygénée et ions iodure', fig: BEAKER('<text x="120" y="100" text-anchor="middle" font-size="12">H₂O₂ + I⁻ (milieu acide)</text>', '#ffd27a'),
    q: TX`Couples : \(\text{H}_2\text{O}_2/\text{H}_2\text{O}\) et \(\text{I}_2/\text{I}^-\).<br>1) Écrire les demi-équations en milieu acide.<br>2) Écrire l’équation de la réaction.<br>3) Comment voit-on que la réaction est lente ?`,
    s: TX`1) \(\text{H}_2\text{O}_2 + 2\text{H}^+ + 2e^- \rightleftharpoons 2\text{H}_2\text{O}\) ; \(\text{I}_2 + 2e^- \rightleftharpoons 2\text{I}^-\).<br>2) \(\text{H}_2\text{O}_2 + 2\text{H}^+ + 2\text{I}^- \to \text{I}_2 + 2\text{H}_2\text{O}\).<br>3) La coloration jaune-brun du diiode apparaît progressivement, en quelques minutes.` },
  { d: 2, t: 'Réactif limitant', fig: TBL(['espèce', 'I⁻', 'S₂O₈²⁻'], [['n₀ (mol)', '2,0×10⁻³', '5,0×10⁻⁴']], 360),
    q: TX`On mélange les quantités du tableau : \(2\,\text{I}^- + \text{S}_2\text{O}_8^{2-} \to \text{I}_2 + 2\,\text{SO}_4^{2-}\) (volume total 100 mL).<br>1) Dresser le tableau d’avancement et trouver \(x_{max}\).<br>2) Calculer les concentrations finales de \(\text{I}_2\) et de \(\text{I}^-\).`,
    s: TX`1) \(\text{I}^-\) : \(x = 1{,}0\times10^{-3}\) ; \(\text{S}_2\text{O}_8^{2-}\) : \(x = 5{,}0\times10^{-4}\) : \(x_{max} = 5{,}0\times10^{-4}\ \text{mol}\).<br>2) \([\text{I}_2] = 5{,}0\times10^{-3}\ \text{mol/L}\) ; \([\text{I}^-] = \dfrac{2{,}0\times10^{-3} - 1{,}0\times10^{-3}}{0{,}100} = 1{,}0\times10^{-2}\ \text{mol/L}\).` },
  { d: 2, t: 'Influence de la température', fig: cfig({ w: 420, h: 220, x1: 40, xs: 10, y1: 6, ys: 1, xl: 't (min)', yl: '[I₂] (mmol/L)', f: t => 5 * (1 - Math.exp(-t / 5)), ext: (X, Y) => `<polyline points="${Array.from({ length: 81 }, (_, i) => { const t = i * 0.5; return X(t).toFixed(1) + ',' + Y(5 * (1 - Math.exp(-t / 15))).toFixed(1); }).join(' ')}" fill="none" stroke="#d93a4a" stroke-width="2.6"/><text x="${X(3)}" y="${Y(5.5)}" fill="#1f6fe0" font-size="11">(1)</text><text x="${X(18)}" y="${Y(3.2)}" fill="#d93a4a" font-size="11">(2)</text>` }),
    q: TX`On réalise la même réaction à 20 °C et à 40 °C ; on obtient les courbes (1) et (2).<br>1) Associer chaque courbe à une température. Justifier.<br>2) L’état final est-il le même ? Pourquoi ?`,
    s: TX`1) (1) monte plus vite : 40 °C ; (2) : 20 °C (la température est un facteur cinétique).<br>2) Oui, \([\text{I}_2]_f = 5\ \text{mmol/L}\) : la température change la vitesse, pas l’état final.` },
  { d: 3, t: 'Trempe et titrage', fig: SVG(300, 160, `<rect x="40" y="60" width="80" height="80" fill="#ffd27a" opacity=".5" stroke="#14213d"/><text x="80" y="156" text-anchor="middle" font-size="11">prélèvement</text><text x="140" y="100" font-size="22">→</text><rect x="180" y="60" width="80" height="80" fill="#cfe0ff" stroke="#14213d"/><text x="220" y="156" text-anchor="middle" font-size="11">eau glacée</text>`),
    q: TX`Pour suivre la formation du diiode, on prélève 10,0 mL du mélange à différents instants, on les verse dans de l’eau glacée, puis on titre le diiode par le thiosulfate à \(1{,}0\times10^{-2}\ \text{mol/L}\) (\(\text{I}_2 + 2\text{S}_2\text{O}_3^{2-} \to 2\text{I}^- + \text{S}_4\text{O}_6^{2-}\)).<br>1) Pourquoi verse-t-on le prélèvement dans l’eau glacée ?<br>2) À \(t = 10\ \text{min}\), l’équivalence est obtenue pour 6,0 mL. Calculer \([\text{I}_2]\).`,
    s: TX`1) Trempe : la dilution et le refroidissement bloquent pratiquement la réaction.<br>2) \(n(\text{I}_2) = \dfrac{1{,}0\times10^{-2}\times6{,}0\times10^{-3}}{2} = 3{,}0\times10^{-5}\ \text{mol}\) ; \([\text{I}_2] = 3{,}0\times10^{-3}\ \text{mol/L}\).` },
]);

addExos('2bc-vitesse', [
  { d: 1, t: 'Lire un temps de demi-réaction', fig: cfig({ w: 420, h: 220, x1: 60, xs: 10, y1: 5, ys: 1, xl: 't (min)', yl: 'x (mmol)', f: t => 4 * (1 - Math.exp(-t / 10)), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(2)}" x2="${X(6.9)}" y2="${Y(2)}" stroke="#d93a4a" stroke-dasharray="4 3"/><line x1="${X(6.9)}" y1="${Y(2)}" x2="${X(6.9)}" y2="${Y(0)}" stroke="#d93a4a" stroke-dasharray="4 3"/>` }),
    q: TX`La courbe donne l’avancement d’une réaction totale.<br>1) Déterminer \(x_f\).<br>2) Déterminer le temps de demi-réaction.<br>3) Au bout de combien de temps peut-on considérer la réaction comme terminée ?`,
    s: TX`1) \(x_f = 4{,}0\ \text{mmol}\).<br>2) \(x = 2{,}0\ \text{mmol}\) pour \(t_{1/2} \approx 7\ \text{min}\).<br>3) Environ 50 min (quelques \(t_{1/2}\)).` },
  { d: 2, t: 'Vitesse à l’origine', fig: cfig({ w: 420, h: 220, x1: 60, xs: 10, y1: 5, ys: 1, xl: 't (min)', yl: 'x (mmol)', f: t => 4 * (1 - Math.exp(-t / 10)), ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(12.5)}" y2="${Y(5)}" stroke="#12946a" stroke-width="2"/>` }),
    q: TX`On reprend la réaction précédente (volume V = 100 mL). La tangente à l’origine est tracée.<br>1) Calculer sa pente en mmol/min.<br>2) En déduire la vitesse volumique initiale en mol·L⁻¹·min⁻¹.<br>3) Comment évolue la vitesse ensuite ? Pourquoi ?`,
    s: TX`1) Pente : \(\dfrac{5{,}0}{12{,}5} = 0{,}40\ \text{mmol/min}\).<br>2) \(v_0 = \dfrac{4{,}0\times10^{-4}}{0{,}100} = 4{,}0\times10^{-3}\ \text{mol·L}^{-1}\text{·min}^{-1}\).<br>3) Elle diminue : la concentration du réactif limitant diminue.` },
  { d: 2, t: 'Suivi par mesure de pression', fig: TBL(['t (min)', '0', '5', '10', '20', '40'], [['P (hPa)', '1013', '1061', '1088', '1113', '1121']], 440),
    q: TX`On suit \(\text{Mg} + 2\text{H}^+ \to \text{Mg}^{2+} + \text{H}_2\) dans un flacon fermé (volume de gaz 0,50 L, T = 293 K).<br>1) Exprimer x en fonction de \(P - P_0\).<br>2) Calculer x à t = 10 min et à t = 40 min.<br>3) Le magnésium est limitant (\(n_0 = 2{,}2\times10^{-3}\ \text{mol}\)). La réaction est-elle terminée à 40 min ?`,
    s: TX`1) \(x = \dfrac{(P - P_0)V}{RT}\).<br>2) \(x_{10} = \dfrac{7500\times5\times10^{-4}}{8{,}31\times293} \approx 1{,}5\times10^{-3}\ \text{mol}\) ; \(x_{40} = \dfrac{10\,800\times5\times10^{-4}}{2435} \approx 2{,}2\times10^{-3}\ \text{mol}\).<br>3) Oui : \(x = x_{max}\).` },
  { d: 3, t: 'Suivi spectrophotométrique', fig: cfig({ w: 420, h: 220, x1: 4, xs: 1, y1: 2, ys: 0.5, xl: 'C (mmol/L)', yl: 'A', f: c => 0.5 * c, fmty: y => String(y).replace('.', ','), ext: (X, Y) => [1, 2, 3].map(c => `<circle cx="${X(c)}" cy="${Y(0.5 * c)}" r="4" fill="#d93a4a"/>`).join('') }),
    q: TX`On suit l’apparition du diiode par spectrophotométrie. La droite d’étalonnage \(A = f([\text{I}_2])\) est donnée.<br>1) Énoncer la loi de Beer-Lambert ; la courbe la vérifie-t-elle ?<br>2) À un instant, A = 0,80. Calculer \([\text{I}_2]\) et x (V = 50 mL).<br>3) Pourquoi cette méthode est-elle adaptée au suivi en continu ?`,
    s: TX`1) \(A = \varepsilon\ell C\) : droite passant par l’origine ✓ (pente 0,5 L/mmol).<br>2) \([\text{I}_2] = 1{,}6\ \text{mmol/L}\) ; \(x = 1{,}6\times10^{-3}\times0{,}050 = 8{,}0\times10^{-5}\ \text{mol}\).<br>3) Elle ne perturbe pas le système et donne des mesures rapides.` },
]);

addExos('2bc-deuxsens', [
  { d: 1, t: 'pH et concentration', fig: TBL(['solution', 'A', 'B', 'C'], [['pH', '2,0', '7,0', '11,5']], 360),
    q: TX`1) Calculer \([\text{H}_3\text{O}^+]\) dans chaque solution.<br>2) Dire si elle est acide, neutre ou basique (25 °C).`,
    s: TX`1) A : \(10^{-2}\) ; B : \(10^{-7}\) ; C : \(3{,}2\times10^{-12}\ \text{mol/L}\).<br>2) A acide ; B neutre ; C basique.` },
  { d: 2, t: 'Acide méthanoïque', fig: BEAKER('<text x="120" y="100" text-anchor="middle" font-size="12">HCOOH 0,010 mol/L</text><text x="120" y="122" text-anchor="middle" font-size="12">pH = 2,9</text>'),
    q: TX`Une solution d’acide méthanoïque à \(C = 1{,}0\times10^{-2}\ \text{mol/L}\) a un pH de 2,9.<br>1) Écrire l’équation de la réaction avec l’eau.<br>2) Calculer le taux d’avancement final.<br>3) La réaction est-elle totale ?`,
    s: TX`1) \(\text{HCOOH} + \text{H}_2\text{O} \rightleftharpoons \text{HCOO}^- + \text{H}_3\text{O}^+\).<br>2) \(\tau = \dfrac{10^{-2{,}9}}{10^{-2}} \approx 0{,}13\).<br>3) Non : elle est limitée.` },
  { d: 2, t: 'L’ammoniac, base faible', fig: BEAKER('<text x="120" y="100" text-anchor="middle" font-size="12">NH₃ 0,010 mol/L</text><text x="120" y="122" text-anchor="middle" font-size="12">pH = 10,6</text>'),
    q: TX`Une solution d’ammoniac à \(1{,}0\times10^{-2}\ \text{mol/L}\) a un pH de 10,6 (\(K_e = 10^{-14}\)).<br>1) Écrire l’équation de la réaction de l’ammoniac avec l’eau.<br>2) Calculer \([\text{HO}^-]\) puis le taux d’avancement final.`,
    s: TX`1) \(\text{NH}_3 + \text{H}_2\text{O} \rightleftharpoons \text{NH}_4^+ + \text{HO}^-\).<br>2) \([\text{HO}^-] = 10^{10{,}6 - 14} \approx 4{,}0\times10^{-4}\ \text{mol/L}\) ; \(\tau \approx 0{,}04\).` },
  { d: 3, t: 'Effet de la dilution', fig: TBL(['C (mol/L)', '0,10', '0,010', '0,0010'], [['pH', '2,9', '3,4', '3,9']], 420),
    q: TX`On mesure le pH de solutions d’acide éthanoïque de concentrations différentes.<br>1) Calculer τ pour chaque solution.<br>2) Comment varie τ avec la dilution ?<br>3) Si l’acide était fort, quels pH aurait-on mesurés ?`,
    s: TX`1) \(\tau \approx 0{,}013\) ; 0,040 ; 0,13.<br>2) τ augmente quand la solution est diluée.<br>3) pH = 1,0 ; 2,0 ; 3,0 (τ = 1).` },
]);

addExos('2bc-equilibre', [
  { d: 1, t: 'Écrire des quotients de réaction', fig: SVG(440, 120, `<text x="20" y="34" font-size="14">a) CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺</text><text x="20" y="66" font-size="14">b) Cu²⁺ + Zn(s) ⇌ Cu(s) + Zn²⁺</text><text x="20" y="98" font-size="14">c) NH₃ + H₂O ⇌ NH₄⁺ + HO⁻</text>`),
    q: TX`Écrire l’expression du quotient de réaction de chaque équation.`,
    s: TX`a) \(Q_r = \dfrac{[\text{CH}_3\text{COO}^-][\text{H}_3\text{O}^+]}{[\text{CH}_3\text{COOH}]}\) ; b) \(Q_r = \dfrac{[\text{Zn}^{2+}]}{[\text{Cu}^{2+}]}\) ; c) \(Q_r = \dfrac{[\text{NH}_4^+][\text{HO}^-]}{[\text{NH}_3]}\).` },
  { d: 2, t: 'Constante d’équilibre à partir de τ', fig: BEAKER('<text x="120" y="100" text-anchor="middle" font-size="12">C = 0,020 mol/L</text><text x="120" y="122" text-anchor="middle" font-size="12">τ = 0,030</text>'),
    q: TX`Une solution d’acide éthanoïque à 0,020 mol/L a un taux d’avancement final de 0,030.<br>1) Exprimer les concentrations à l’équilibre en fonction de C et τ.<br>2) Montrer que \(K = \dfrac{C\tau^2}{1 - \tau}\) et la calculer.`,
    s: TX`1) \([\text{H}_3\text{O}^+] = [\text{CH}_3\text{COO}^-] = C\tau\) ; \([\text{CH}_3\text{COOH}] = C(1 - \tau)\).<br>2) \(K = \dfrac{(C\tau)^2}{C(1 - \tau)} = \dfrac{0{,}02\times9\times10^{-4}}{0{,}97} \approx 1{,}9\times10^{-5}\).` },
  { d: 2, t: 'K par conductimétrie', fig: TBL(['ion', 'λ (mS·m²·mol⁻¹)'], [['H₃O⁺', '35,0'], ['HCOO⁻', '5,46']], 320),
    q: TX`Une solution d’acide méthanoïque à \(1{,}0\times10^{-2}\ \text{mol/L}\) a une conductivité \(\sigma = 5{,}06\times10^{-2}\ \text{S/m}\).<br>1) Calculer \([\text{H}_3\text{O}^+]_{éq}\) en mol/m³ puis en mol/L.<br>2) Calculer τ et K.`,
    s: TX`1) \([\text{H}_3\text{O}^+] = \dfrac{5{,}06\times10^{-2}}{(35{,}0 + 5{,}46)\times10^{-3}} \approx 1{,}25\ \text{mol/m}^3 = 1{,}25\times10^{-3}\ \text{mol/L}\).<br>2) \(\tau = 0{,}125\) ; \(K = \dfrac{10^{-2}\times0{,}125^2}{0{,}875} \approx 1{,}8\times10^{-4}\).` },
  { d: 3, t: 'Une réaction presque totale', fig: SVG(380, 100, `<text x="190" y="40" text-anchor="middle" font-size="14">CH₃COOH + NH₃ ⇌ CH₃COO⁻ + NH₄⁺</text><text x="190" y="72" text-anchor="middle" font-size="13">pK_A1 = 4,8 ; pK_A2 = 9,2</text>`),
    q: TX`On mélange 1,0 mmol d’acide éthanoïque et 1,0 mmol d’ammoniac dans 100 mL d’eau.<br>1) Calculer la constante d’équilibre K.<br>2) En notant \(x_f\) l’avancement final, montrer que \(K = \dfrac{x_f^2}{(n_0 - x_f)^2}\).<br>3) Calculer τ. Conclure.`,
    s: TX`1) \(K = 10^{9{,}2 - 4{,}8} \approx 2{,}5\times10^{4}\).<br>2) Le volume se simplifie ; produits : \(x_f\), réactifs : \(n_0 - x_f\).<br>3) \(\dfrac{\tau}{1 - \tau} = \sqrt K \approx 158 \Rightarrow \tau \approx 0{,}994\) : pratiquement totale.` },
]);

addExos('2bc-acidebase', [
  { d: 1, t: 'Produit ionique de l’eau', fig: TBL(['solution', 'pH', '[H₃O⁺]', '[HO⁻]'], [['A', '3', '?', '?'], ['B', '?', '?', '10⁻⁵ mol/L']], 440),
    q: TX`Compléter le tableau (\(K_e = 10^{-14}\) à 25 °C).`,
    s: TX`A : \([\text{H}_3\text{O}^+] = 10^{-3}\), \([\text{HO}^-] = 10^{-11}\ \text{mol/L}\). B : \([\text{H}_3\text{O}^+] = 10^{-9}\ \text{mol/L}\), pH = 9.` },
  { d: 2, t: 'Diagrammes de prédominance', fig: SVG(440, 120, `<line x1="20" y1="40" x2="420" y2="40" stroke="#14213d" stroke-width="2"/><line x1="20" y1="90" x2="420" y2="90" stroke="#14213d" stroke-width="2"/>${[[3.75, 40, 'HCOOH / HCOO⁻'], [9.2, 90, 'NH₄⁺ / NH₃']].map(([p, y, n]) => `<line x1="${20 + p * 28}" y1="${y - 10}" x2="${20 + p * 28}" y2="${y + 10}" stroke="#d93a4a" stroke-width="2"/><text x="${24 + p * 28}" y="${y - 14}" font-size="11">pK_A = ${String(p).replace('.', ',')}</text><text x="${300}" y="${y + 24}" font-size="11">${n}</text>`).join('')}<line x1="216" y1="20" x2="216" y2="110" stroke="#12946a" stroke-dasharray="4 3"/><text x="220" y="114" fill="#12946a" font-size="11">pH = 7</text>`),
    q: TX`On donne les pK_A des couples \(\text{HCOOH}/\text{HCOO}^-\) (3,75) et \(\text{NH}_4^+/\text{NH}_3\) (9,2).<br>1) Tracer les diagrammes de prédominance.<br>2) Quelles espèces prédominent dans une solution de pH 7 ?<br>3) Quel est l’acide le plus fort ?`,
    s: TX`1) Forme acide à gauche du pK_A, forme basique à droite.<br>2) \(\text{HCOO}^-\) et \(\text{NH}_4^+\).<br>3) L’acide méthanoïque (pK_A le plus petit).` },
  { d: 2, t: 'Couleur d’un indicateur', fig: SVG(440, 80, `<rect x="20" y="20" width="160" height="30" fill="#ffd27a"/><rect x="180" y="20" width="80" height="30" fill="#7ad38f"/><rect x="260" y="20" width="160" height="30" fill="#6aa5ff"/><text x="200" y="70" font-size="11">zone de virage du BBT (6,0 – 7,6)</text>`),
    q: TX`Le bleu de bromothymol (\(\text{p}K_A = 7{,}1\)) est jaune sous sa forme acide et bleu sous sa forme basique.<br>1) Quelle couleur prend-il dans une solution de pH 5 ? de pH 9 ?<br>2) Calculer le rapport \([\text{Ind}^-]/[\text{HInd}]\) à pH 9.<br>3) Pourquoi la zone de virage est-elle d’environ 2 unités de pH ?`,
    s: TX`1) Jaune ; bleu.<br>2) \(10^{9 - 7{,}1} \approx 79\).<br>3) Une forme impose sa couleur quand elle est environ 10 fois plus concentrée que l’autre : \(\text{p}K_A \pm 1\).` },
  { d: 3, t: 'Proportion d’acide dissocié', fig: BEAKER('<text x="120" y="100" text-anchor="middle" font-size="12">tampon à pH = 6,0</text>'),
    q: TX`Une solution contient le couple \(\text{CH}_3\text{COOH}/\text{CH}_3\text{COO}^-\) (\(\text{p}K_A = 4{,}8\)) à pH = 6,0.<br>1) Calculer le rapport \([\text{CH}_3\text{COO}^-]/[\text{CH}_3\text{COOH}]\).<br>2) En déduire le pourcentage de la forme acide.<br>3) À quel pH les deux formes sont-elles en même quantité ?`,
    s: TX`1) \(10^{6{,}0 - 4{,}8} = 10^{1{,}2} \approx 15{,}8\).<br>2) \(\dfrac{1}{1 + 15{,}8} \approx 6\ \%\).<br>3) pH = pK_A = 4,8.` },
]);

addExos('2bc-dosage', [
  { d: 1, t: 'Relation à l’équivalence', fig: SVG(240, 220, `<rect x="110" y="10" width="20" height="120" fill="#fff" stroke="#14213d" stroke-width="2"/><rect x="112" y="30" width="16" height="98" fill="#6aa5ff" opacity=".5"/><path d="M80 160 h80 v50 h-80 z" fill="#ffd27a" opacity=".5" stroke="#14213d" stroke-width="2"/><text x="140" y="60" font-size="11">NaOH 0,10 mol/L</text><text x="166" y="190" font-size="11">20,0 mL d’acide</text>`),
    q: TX`On dose 20,0 mL d’une solution d’acide chlorhydrique par la soude à 0,10 mol/L ; \(V_{BE} = 15{,}0\ \text{mL}\).<br>1) Écrire l’équation du dosage.<br>2) Calculer la concentration de l’acide.<br>3) Quel est le pH à l’équivalence ?`,
    s: TX`1) \(\text{H}_3\text{O}^+ + \text{HO}^- \to 2\text{H}_2\text{O}\).<br>2) \(C_A = \dfrac{0{,}10\times15{,}0}{20{,}0} = 7{,}5\times10^{-2}\ \text{mol/L}\).<br>3) pH = 7 (solution de chlorure de sodium).` },
  { d: 2, t: 'Lire une courbe de dosage', fig: cfig({ w: 420, h: 240, x1: 20, xs: 4, y1: 14, ys: 2, xl: 'V_B (mL)', yl: 'pH', f: V => V < 9.95 ? 4.8 + Math.log10((V / 10 + 0.01) / (1 - V / 10 + 0.001)) : 12.2 - 3.5 * Math.exp(-(V - 10) * 1.3), ext: (X, Y) => `<line x1="${X(10)}" y1="${Y(0)}" x2="${X(10)}" y2="${Y(8.7)}" stroke="#d93a4a" stroke-dasharray="4 3"/><line x1="${X(5)}" y1="${Y(0)}" x2="${X(5)}" y2="${Y(4.8)}" stroke="#12946a" stroke-dasharray="4 3"/>` }),
    q: TX`On dose 10,0 mL d’un acide faible AH par la soude à 0,10 mol/L.<br>1) Déterminer \(V_{BE}\) et \(\text{pH}_E\).<br>2) Calculer la concentration de l’acide.<br>3) Déterminer le pK_A du couple AH/A⁻ et identifier l’acide.`,
    s: TX`1) \(V_{BE} = 10\ \text{mL}\) ; \(\text{pH}_E \approx 8{,}7\).<br>2) \(C_A = \dfrac{0{,}10\times10}{10} = 0{,}10\ \text{mol/L}\).<br>3) À 5 mL, pH = pK_A ≈ 4,8 : acide éthanoïque.` },
  { d: 2, t: 'Choisir un indicateur', fig: TBL(['indicateur', 'zone de virage'], [['hélianthine', '3,1 – 4,4'], ['BBT', '6,0 – 7,6'], ['phénolphtaléine', '8,2 – 10']], 360),
    q: TX`Pour le dosage de l’exercice précédent (\(\text{pH}_E \approx 8{,}7\)), quel indicateur choisir ? Justifier. Quelle erreur commettrait-on avec l’hélianthine ?`,
    s: TX`La phénolphtaléine : sa zone de virage contient \(\text{pH}_E\). Avec l’hélianthine, le virage aurait lieu vers pH 4 : bien avant l’équivalence (volume trouvé trop petit).` },
  { d: 3, t: 'Dosage d’un comprimé d’aspirine', fig: SVG(220, 160, `<circle cx="110" cy="80" r="55" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="110" y="76" text-anchor="middle" font-size="12">Aspirine</text><text x="110" y="94" text-anchor="middle" font-size="12">500 mg</text>`),
    q: TX`On dissout un comprimé d’aspirine (acide acétylsalicylique, monoacide, \(M = 180\ \text{g/mol}\)) dans l’eau et on le dose entièrement par la soude à 0,20 mol/L : \(V_{BE} = 13{,}9\ \text{mL}\).<br>1) Calculer la quantité d’acide dans le comprimé.<br>2) Calculer sa masse et la comparer à l’indication.`,
    s: TX`1) \(n = 0{,}20\times13{,}9\times10^{-3} \approx 2{,}78\times10^{-3}\ \text{mol}\).<br>2) \(m = 2{,}78\times10^{-3}\times180 \approx 0{,}50\ \text{g}\) : conforme.` },
]);

addExos('2bc-spontanee', [
  { d: 1, t: 'Prévoir le sens d’évolution', fig: TBL(['état', 'Q_r,i', 'K'], [['a', '10⁻⁴', '10²'], ['b', '50', '2'], ['c', '3,2', '3,2']], 360),
    q: TX`Pour chaque état initial du tableau, prévoir le sens d’évolution spontanée.`,
    s: TX`a) \(Q_{r,i} < K\) : sens direct. b) \(Q_{r,i} > K\) : sens inverse. c) Équilibre : pas d’évolution.` },
  { d: 2, t: 'Mélange acide-base', fig: SVG(420, 100, `<text x="210" y="40" text-anchor="middle" font-size="14">CH₃COOH + HCOO⁻ ⇌ CH₃COO⁻ + HCOOH</text><text x="210" y="72" text-anchor="middle" font-size="12">pK_A(CH₃COOH) = 4,8 ; pK_A(HCOOH) = 3,75</text>`),
    q: TX`On mélange quatre espèces, chacune à la concentration initiale \(1{,}0\times10^{-2}\ \text{mol/L}\) (dans le mélange).<br>1) Calculer K.<br>2) Calculer \(Q_{r,i}\).<br>3) Prévoir le sens d’évolution.`,
    s: TX`1) \(K = 10^{3{,}75 - 4{,}8} \approx 0{,}089\).<br>2) \(Q_{r,i} = 1\).<br>3) \(Q_{r,i} > K\) : sens inverse (formation d’acide éthanoïque et d’ions méthanoate).` },
  { d: 2, t: 'Cuivre et ions argent', fig: BEAKER('<rect x="114" y="10" width="10" height="130" fill="#c0392b" opacity=".7"/><text x="140" y="100" font-size="11">Ag⁺, Cu²⁺</text>'),
    q: TX`On plonge un fil de cuivre dans une solution contenant \([\text{Ag}^+]_i = 0{,}10\ \text{mol/L}\) et \([\text{Cu}^{2+}]_i = 0{,}10\ \text{mol/L}\). Pour \(\text{Cu} + 2\text{Ag}^+ \rightleftharpoons \text{Cu}^{2+} + 2\text{Ag}\), \(K = 2\times10^{15}\).<br>1) Écrire \(Q_r\) et calculer \(Q_{r,i}\).<br>2) Prévoir l’évolution et les observations.`,
    s: TX`1) \(Q_r = \dfrac{[\text{Cu}^{2+}]}{[\text{Ag}^+]^2}\) ; \(Q_{r,i} = \dfrac{0{,}10}{0{,}010} = 10\).<br>2) \(Q_{r,i} \ll K\) : sens direct. Dépôt d’argent sur le fil, la solution bleuit.` },
  { d: 3, t: 'Ions fer (III) et iodure', fig: SVG(420, 90, `<text x="210" y="40" text-anchor="middle" font-size="14">2 Fe³⁺ + 2 I⁻ ⇌ 2 Fe²⁺ + I₂ ; K = 1,0×10⁵</text>`),
    q: TX`Dans un mélange, on a initialement \([\text{Fe}^{3+}] = [\text{I}^-] = 1{,}0\times10^{-2}\), \([\text{Fe}^{2+}] = 0{,}10\) et \([\text{I}_2] = 0{,}10\ \text{mol/L}\).<br>1) Écrire \(Q_r\) et calculer \(Q_{r,i}\).<br>2) Prévoir le sens d’évolution.<br>3) Que deviendrait le sens si l’on retirait les ions \(\text{Fe}^{2+}\) et le diiode ?`,
    s: TX`1) \(Q_r = \dfrac{[\text{Fe}^{2+}]^2[\text{I}_2]}{[\text{Fe}^{3+}]^2[\text{I}^-]^2}\) ; \(Q_{r,i} = \dfrac{0{,}01\times0{,}1}{10^{-4}\times10^{-4}} = 1{,}0\times10^{5}\).<br>2) \(Q_{r,i} = K\) : le système est à l’équilibre, pas d’évolution.<br>3) \(Q_{r,i} = 0 < K\) : sens direct.` },
]);

const CELL = (l, r, lc, rc) => SVG(440, 190, `<rect x="40" y="80" width="120" height="100" fill="${lc}" opacity=".45" stroke="#14213d" stroke-width="2"/><rect x="280" y="80" width="120" height="100" fill="${rc}" opacity=".45" stroke="#14213d" stroke-width="2"/><rect x="92" y="50" width="14" height="110" fill="#9aa6bf"/><rect x="332" y="50" width="14" height="110" fill="#9aa6bf"/><path d="M130 100 V64 H310 V100" fill="none" stroke="#d98200" stroke-width="10"/><path d="M99 50 V16 H339 V50" fill="none" stroke="#14213d" stroke-width="2"/><text x="60" y="176" font-size="11">${l}</text><text x="290" y="176" font-size="11">${r}</text>`);
addExos('2bc-piles', [
  { d: 1, t: 'Pile cuivre – argent', fig: CELL('Cu | Cu²⁺', 'Ag | Ag⁺', '#6aa5ff', '#eef2f8'),
    q: TX`On réalise une pile avec une demi-pile \(\text{Cu}/\text{Cu}^{2+}\) et une demi-pile \(\text{Ag}/\text{Ag}^+\). L’électrode d’argent est le pôle positif.<br>1) Écrire les réactions aux électrodes et l’équation de fonctionnement.<br>2) Donner le schéma conventionnel de la pile.<br>3) Indiquer le sens du courant et des électrons dans le circuit extérieur.`,
    s: TX`1) Anode : \(\text{Cu} \to \text{Cu}^{2+} + 2e^-\) ; cathode : \(\text{Ag}^+ + e^- \to \text{Ag}\) ; bilan \(\text{Cu} + 2\text{Ag}^+ \to \text{Cu}^{2+} + 2\text{Ag}\).<br>2) \(\ominus\ \text{Cu}\,|\,\text{Cu}^{2+}\,\|\,\text{Ag}^+\,|\,\text{Ag}\ \oplus\).<br>3) Courant de l’argent vers le cuivre ; électrons du cuivre vers l’argent.` },
  { d: 2, t: 'Usure d’une électrode', fig: CELL('Zn | Zn²⁺', 'Cu | Cu²⁺', '#cfd8e6', '#6aa5ff'),
    q: TX`Une pile Daniell débite un courant constant de 50 mA pendant 2,0 h. \(\mathcal F = 96\,500\ \text{C/mol}\), \(M(\text{Zn}) = 65{,}4\ \text{g/mol}\).<br>1) Calculer la quantité d’électricité débitée.<br>2) Calculer la quantité d’électrons échangés et l’avancement.<br>3) Calculer la variation de masse de l’électrode de zinc.`,
    s: TX`1) \(Q = 0{,}050\times7200 = 360\ \text{C}\).<br>2) \(n(e^-) = \dfrac{360}{96\,500} \approx 3{,}7\times10^{-3}\ \text{mol}\) ; \(x = 1{,}9\times10^{-3}\ \text{mol}\).<br>3) \(\Delta m = -x\,M \approx -0{,}12\ \text{g}\).` },
  { d: 2, t: 'Capacité d’une pile', fig: CELL('Zn | Zn²⁺', 'Ag | Ag⁺ (50 mL ; 0,10 mol/L)', '#cfd8e6', '#eef2f8'),
    q: TX`Dans une pile zinc – argent, le réactif limitant est l’ion \(\text{Ag}^+\) : 50 mL à 0,10 mol/L. Équation : \(\text{Zn} + 2\text{Ag}^+ \to \text{Zn}^{2+} + 2\text{Ag}\).<br>1) Calculer \(x_{max}\).<br>2) Combien d’électrons sont échangés par réaction ? Calculer la capacité \(Q_{max}\).<br>3) Durée de fonctionnement sous 20 mA ?`,
    s: TX`1) \(n(\text{Ag}^+) = 5{,}0\times10^{-3}\ \text{mol}\) : \(x_{max} = 2{,}5\times10^{-3}\ \text{mol}\).<br>2) z = 2 : \(Q_{max} = 2\times2{,}5\times10^{-3}\times96\,500 \approx 483\ \text{C}\).<br>3) \(\Delta t = \dfrac{483}{0{,}020} \approx 2{,}4\times10^{4}\ \text{s} \approx 6{,}7\ \text{h}\).` },
  { d: 3, t: 'Durée de vie d’une pile Daniell', fig: CELL('Zn (en excès)', 'Cu²⁺ : 100 mL ; 0,50 mol/L', '#cfd8e6', '#6aa5ff'),
    q: TX`Une pile Daniell contient 100 mL de solution de sulfate de cuivre à 0,50 mol/L ; le zinc est en excès. Elle débite 0,10 A.<br>1) Calculer \(x_{max}\) et la quantité d’électricité maximale.<br>2) Calculer la durée de fonctionnement maximale.<br>3) Que vaut alors la masse de cuivre déposée (\(M = 63{,}5\ \text{g/mol}\)) ?`,
    s: TX`1) \(x_{max} = 0{,}050\ \text{mol}\) ; \(Q_{max} = 2\times0{,}050\times96\,500 = 9650\ \text{C}\).<br>2) \(\Delta t = 96\,500\ \text{s} \approx 26{,}8\ \text{h}\).<br>3) \(m = 0{,}050\times63{,}5 \approx 3{,}2\ \text{g}\).` },
]);

addExos('2bc-electrolyse', [
  { d: 1, t: 'Électrolyse du chlorure de cuivre', fig: SVG(380, 200, `<rect x="60" y="80" width="260" height="110" fill="#6aa5ff" opacity=".35" stroke="#14213d" stroke-width="2"/><rect x="110" y="50" width="14" height="120" fill="#5b6577"/><rect x="256" y="50" width="14" height="120" fill="#5b6577"/><path d="M117 50 V20 H263 V50" fill="none" stroke="#14213d" stroke-width="2"/><text x="96" y="40">−</text><text x="270" y="40">+</text>`),
    q: TX`On électrolyse une solution de chlorure de cuivre \((\text{Cu}^{2+} + 2\text{Cl}^-)\) avec des électrodes de graphite.<br>1) Nommer chaque électrode et écrire la réaction qui s’y produit.<br>2) Écrire l’équation de l’électrolyse.<br>3) Cette transformation est-elle spontanée ?`,
    s: TX`1) Cathode (−) : \(\text{Cu}^{2+} + 2e^- \to \text{Cu}\) ; anode (+) : \(2\text{Cl}^- \to \text{Cl}_2 + 2e^-\).<br>2) \(\text{Cu}^{2+} + 2\text{Cl}^- \to \text{Cu} + \text{Cl}_2\).<br>3) Non : elle est forcée par le générateur (la réaction inverse est spontanée).` },
  { d: 2, t: 'Nickelage', fig: SVG(380, 180, `<rect x="60" y="70" width="260" height="100" fill="#a8e6c9" opacity=".5" stroke="#14213d" stroke-width="2"/><rect x="110" y="40" width="20" height="110" fill="#9aa6bf"/><text x="70" y="34" font-size="11">objet (cathode)</text><rect x="256" y="40" width="14" height="110" fill="#5b6577"/><text x="236" y="34" font-size="11">nickel (anode)</text>`),
    q: TX`On recouvre un objet de nickel en électrolysant une solution d’ions \(\text{Ni}^{2+}\) sous 2,0 A pendant 30 min. \(M(\text{Ni}) = 58{,}7\ \text{g/mol}\).<br>1) À quelle borne du générateur relie-t-on l’objet ? Écrire la réaction.<br>2) Calculer la masse de nickel déposée.`,
    s: TX`1) Au pôle − (cathode) : \(\text{Ni}^{2+} + 2e^- \to \text{Ni}\).<br>2) \(m = \dfrac{I\Delta t\,M}{2\mathcal F} = \dfrac{2\times1800\times58{,}7}{2\times96\,500} \approx 1{,}1\ \text{g}\).` },
  { d: 2, t: 'Électrolyse de l’eau', fig: SVG(300, 200, `<rect x="40" y="110" width="220" height="80" fill="#6aa5ff" opacity=".35" stroke="#14213d" stroke-width="2"/><rect x="80" y="20" width="30" height="130" fill="#fff" stroke="#14213d"/><rect x="190" y="20" width="30" height="130" fill="#fff" stroke="#14213d"/><rect x="82" y="22" width="26" height="60" fill="#eaf1fd"/><rect x="192" y="22" width="26" height="30" fill="#eaf1fd"/><text x="70" y="14" font-size="11">H₂</text><text x="186" y="14" font-size="11">O₂</text>`),
    q: TX`On électrolyse de l’eau acidulée sous 1,0 A pendant 1,0 h (\(V_m = 24\ \text{L/mol}\)).<br>1) Écrire les réactions aux électrodes.<br>2) Calculer les volumes de dihydrogène et de dioxygène recueillis.<br>3) Le rapport des volumes est-il cohérent avec la figure ?`,
    s: TX`1) Cathode : \(2\text{H}^+ + 2e^- \to \text{H}_2\) ; anode : \(2\text{H}_2\text{O} \to \text{O}_2 + 4\text{H}^+ + 4e^-\).<br>2) \(n(e^-) = \dfrac{3600}{96\,500} \approx 3{,}7\times10^{-2}\ \text{mol}\) ; \(V(\text{H}_2) \approx 0{,}45\ \text{L}\) ; \(V(\text{O}_2) \approx 0{,}22\ \text{L}\).<br>3) Oui : deux fois plus de dihydrogène.` },
  { d: 3, t: 'Argenture d’un couvert', fig: SVG(300, 140, `<path d="M40 70 h170 q30 0 40 -20 q10 20 -20 40 h-190 z" fill="#d9e4f5" stroke="#14213d" stroke-width="2"/><text x="60" y="120" font-size="11">surface 50 cm² ; épaisseur 10 µm</text>`),
    q: TX`On veut déposer une couche d’argent de 10 µm d’épaisseur sur un couvert de surface 50 cm² (\(\rho = 10{,}5\ \text{g/cm}^3\), \(M = 108\ \text{g/mol}\)), sous 0,50 A.<br>1) Calculer la masse d’argent à déposer.<br>2) Calculer la quantité d’électricité nécessaire (\(\text{Ag}^+ + e^- \to \text{Ag}\)).<br>3) Calculer la durée de l’électrolyse.`,
    s: TX`1) \(V = 50\times10^{-3} = 0{,}050\ \text{cm}^3\) ; \(m = 0{,}525\ \text{g}\).<br>2) \(n = 4{,}86\times10^{-3}\ \text{mol}\) ; \(Q = n\mathcal F \approx 469\ \text{C}\).<br>3) \(\Delta t = \dfrac{469}{0{,}50} \approx 938\ \text{s} \approx 16\ \text{min}\).` },
]);

addExos('2bc-ester', [
  { d: 1, t: 'Nommer des esters', fig: SVG(440, 120, `<text x="20" y="34" font-size="14">a) HCOO–CH₂–CH₃</text><text x="20" y="66" font-size="14">b) CH₃–COO–CH₂–CH₂–CH₃</text><text x="20" y="98" font-size="14">c) CH₃–CH₂–COO–CH₃</text>`),
    q: TX`1) Nommer chaque ester.<br>2) Donner l’acide et l’alcool permettant de le synthétiser.`,
    s: TX`a) Méthanoate d’éthyle (acide méthanoïque + éthanol). b) Éthanoate de propyle (acide éthanoïque + propan-1-ol). c) Propanoate de méthyle (acide propanoïque + méthanol).` },
  { d: 2, t: 'Constante d’équilibre', fig: TBL(['', 'acide', 'alcool', 'ester', 'eau'], [['initial (mol)', '1', '1', '0', '0'], ['équilibre (mol)', '?', '?', '0,67', '?']], 440),
    q: TX`On mélange 1 mol d’acide éthanoïque et 1 mol d’éthanol ; à l’équilibre il s’est formé 0,67 mol d’ester.<br>1) Compléter le tableau.<br>2) Calculer K.<br>3) Calculer le rendement.`,
    s: TX`1) Acide : 0,33 ; alcool : 0,33 ; eau : 0,67 mol.<br>2) \(K = \dfrac{0{,}67^2}{0{,}33^2} \approx 4{,}1\).<br>3) \(r = 67\ \%\).` },
  { d: 2, t: 'Alcool en excès', fig: TBL(['acide', 'alcool', 'K'], [['1 mol', '3 mol', '4']], 300),
    q: TX`On mélange 1 mol d’acide et 3 mol d’alcool primaire (K = 4).<br>1) Montrer que \(x_f\) vérifie \(3x^2 - 16x + 12 = 0\).<br>2) Calculer \(x_f\) et le rendement. Comparer au mélange équimolaire.`,
    s: TX`1) \(\dfrac{x^2}{(1 - x)(3 - x)} = 4 \Rightarrow x^2 = 4(3 - 4x + x^2) \Rightarrow 3x^2 - 16x + 12 = 0\).<br>2) \(x_f = \dfrac{16 - \sqrt{112}}{6} \approx 0{,}90\ \text{mol}\) (l’autre racine > 1) : \(r \approx 90\ \%\) contre 67 %.` },
  { d: 3, t: 'Hydrolyse d’un ester', fig: TBL(['', 'ester', 'eau', 'acide', 'alcool'], [['initial (mol)', '1', '1', '0', '0']], 440),
    q: TX`On mélange 1 mol d’éthanoate d’éthyle et 1 mol d’eau (K de l’estérification = 4).<br>1) Écrire l’équation de l’hydrolyse et sa constante K′.<br>2) Calculer la composition à l’équilibre.<br>3) Comparer avec l’estérification d’un mélange équimolaire.`,
    s: TX`1) \(\text{CH}_3\text{COOC}_2\text{H}_5 + \text{H}_2\text{O} \rightleftharpoons \text{CH}_3\text{COOH} + \text{C}_2\text{H}_5\text{OH}\) ; \(K' = 1/K = 0{,}25\).<br>2) \(\dfrac{x^2}{(1 - x)^2} = 0{,}25 \Rightarrow x = 0{,}33\ \text{mol}\) : ester 0,67 ; eau 0,67 ; acide 0,33 ; alcool 0,33 mol.<br>3) Même état final : les deux réactions conduisent au même équilibre.` },
]);

addExos('2bc-controle', [
  { d: 1, t: 'Synthèse de l’aspirine', fig: SVG(440, 100, `<text x="220" y="40" text-anchor="middle" font-size="14">acide salicylique + anhydride éthanoïque →</text><text x="220" y="70" text-anchor="middle" font-size="14">aspirine + acide éthanoïque</text>`),
    q: TX`1) Pourquoi utilise-t-on l’anhydride éthanoïque plutôt que l’acide éthanoïque ?<br>2) Écrire la formule de l’anhydride éthanoïque.<br>3) Quel est le rôle de quelques gouttes d’acide sulfurique ?`,
    s: TX`1) La réaction est rapide et totale (pas d’eau formée, pas d’hydrolyse).<br>2) \((\text{CH}_3\text{CO})_2\text{O}\).<br>3) Catalyseur : il accélère la réaction.` },
  { d: 2, t: 'Rendement de la synthèse de l’aspirine', fig: TBL(['espèce', 'M (g/mol)'], [['acide salicylique', '138'], ['aspirine', '180']], 320),
    q: TX`On fait réagir 2,76 g d’acide salicylique avec un excès d’anhydride éthanoïque ; on obtient 2,9 g d’aspirine purifiée.<br>1) Calculer la quantité d’acide salicylique.<br>2) Calculer la masse maximale d’aspirine.<br>3) Calculer le rendement.`,
    s: TX`1) \(n = \dfrac{2{,}76}{138} = 0{,}020\ \text{mol}\).<br>2) \(m_{max} = 0{,}020\times180 = 3{,}6\ \text{g}\).<br>3) \(r = \dfrac{2{,}9}{3{,}6} \approx 81\ \%\).` },
  { d: 2, t: 'Saponification d’un ester', fig: BEAKER('<text x="120" y="96" text-anchor="middle" font-size="12">ester + soude</text><text x="120" y="116" text-anchor="middle" font-size="12">(chauffage)</text>'),
    q: TX`On chauffe 0,10 mol d’éthanoate d’éthyle avec 0,15 mol d’ions hydroxyde.<br>1) Écrire l’équation de la saponification.<br>2) Calculer l’état final (réaction totale).<br>3) Pourquoi parle-t-on d’hydrolyse « basique » ?`,
    s: TX`1) \(\text{CH}_3\text{COOC}_2\text{H}_5 + \text{HO}^- \to \text{CH}_3\text{COO}^- + \text{C}_2\text{H}_5\text{OH}\).<br>2) Ester limitant : il reste 0,05 mol de \(\text{HO}^-\) ; 0,10 mol d’ions éthanoate et 0,10 mol d’éthanol.<br>3) Elle se fait avec des ions hydroxyde.` },
  { d: 3, t: 'Fabriquer un savon', fig: SVG(440, 140, `<rect x="20" y="40" width="120" height="70" rx="10" fill="#ffd27a" stroke="#14213d"/><text x="80" y="80" text-anchor="middle" font-size="11">oléine</text><text x="160" y="80" font-size="20">+ 3 HO⁻ →</text><rect x="270" y="40" width="150" height="70" rx="10" fill="#eaf1fd" stroke="#14213d"/><text x="345" y="72" text-anchor="middle" font-size="11">3 oléate de sodium</text><text x="345" y="90" text-anchor="middle" font-size="11">+ glycérol</text>`),
    q: TX`On saponifie 10 g d’oléine (trioléate de glycéryle, \(M = 884\ \text{g/mol}\)) par un excès de soude. Une molécule d’oléine donne trois ions oléate ; l’oléate de sodium a pour masse molaire 304 g/mol. On obtient 8,5 g de savon sec.<br>1) Calculer la quantité d’oléine.<br>2) Calculer la masse maximale de savon.<br>3) Calculer le rendement.`,
    s: TX`1) \(n = \dfrac{10}{884} \approx 1{,}13\times10^{-2}\ \text{mol}\).<br>2) \(n(\text{savon}) = 3n \approx 3{,}39\times10^{-2}\ \text{mol}\) ; \(m_{max} \approx 10{,}3\ \text{g}\).<br>3) \(r \approx 83\ \%\).` },
]);
